import type { RawQ } from "../types";
// ʿUlūm al-Qurʾān, revelation: waḥy and its modes, first and last revelations, tanjīm, Laylat al-Qadr and the descent, asbāb al-nuzūl, Meccan and Medinan, names of the Quran, counts, scribes. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  // ---------- waḥy and its modes ----------
  { id: "ulr-001", s: "ulum", g: 1, d: 1, t: ["wahy", "jibril"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on how the revelation descended",
    en: ["Which angel brought the Quran down to the Prophet ﷺ?", ["Jibrīl", "Mīkāʾīl", "Isrāfīl", "Mālik"], "Jibrīl is the angel of revelation who brought the Quran to the Prophet ﷺ. Mīkāʾīl, Isrāfīl and Mālik have other tasks."],
    de: ["Welcher Engel brachte den Koran zum Propheten ﷺ herab?", ["Jibrīl", "Mīkāʾīl", "Isrāfīl", "Mālik"], "Jibrīl ist der Engel der Offenbarung, der den Koran zum Propheten ﷺ brachte. Mīkāʾīl, Isrāfīl und Mālik haben andere Aufgaben."],
    ar: ["مَن المَلَك الذي نزل بالقرآن على النبي ﷺ؟", ["جبريل", "ميكائيل", "إسرافيل", "مالك"], "جبريل عليه السلام هو أمين الوحي الذي نزل بالقرآن على النبي ﷺ، ولميكائيل وإسرافيل ومالك وظائف أخرى."] },
  { id: "ulr-002", s: "ulum", g: 1, d: 1, t: ["first-revelation", "wahy"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb Badʾ al-Waḥy",
    en: ["Where was the Prophet ﷺ when the first revelation came to him?", ["In the cave of Ḥirāʾ", "In the cave of Thawr", "In the Masjid al-Ḥarām", "On the plain of ʿArafa"], "According to the hadith of ʿĀʾisha in Ṣaḥīḥ al-Bukhārī, the Prophet ﷺ used to seclude himself in the cave of Ḥirāʾ, and the angel came to him there. The cave of Thawr is linked to the hijra."],
    de: ["Wo befand sich der Prophet ﷺ, als die erste Offenbarung zu ihm kam?", ["In der Höhle Ḥirāʾ", "In der Höhle Thawr", "In der Masjid al-Ḥarām", "In der Ebene von ʿArafa"], "Nach dem Hadith von ʿĀʾisha in Ṣaḥīḥ al-Bukhārī zog sich der Prophet ﷺ in die Höhle Ḥirāʾ zurück, und dort kam der Engel zu ihm. Die Höhle Thawr gehört zur Hidschra."],
    ar: ["أين كان النبي ﷺ حين جاءه الوحي أول مرة؟", ["في غار حراء", "في غار ثور", "في المسجد الحرام", "في صعيد عرفة"], "في حديث عائشة عند البخاري أن النبي ﷺ كان يتحنث في غار حراء فجاءه الملك فيه، أما غار ثور فمرتبط بالهجرة."] },
  { id: "ulr-003", s: "ulum", g: 1, d: 1, t: ["first-revelation"], src: "al-Suyūṭī, al-Itqān, ch. on the first revelation", v: "96:1",
    en: ["According to the soundest view, which passage was revealed first? (Its first verse is shown.)", ["The opening verses of Sūrat al-ʿAlaq", "The opening verses of Sūrat al-Muddaththir", "The whole of Sūrat al-Fātiḥa", "The opening verses of Sūrat al-Baqara"], "The soundest view, based on the hadith of ʿĀʾisha in al-Bukhārī and Muslim, is that the opening verses of al-ʿAlaq came first. Al-Muddaththir and al-Fātiḥa are other, weaker views."],
    de: ["Welche Passage wurde nach der richtigsten Ansicht zuerst offenbart? (Ihr erster Vers wird gezeigt.)", ["Die Anfangsverse der Sūrat al-ʿAlaq", "Die Anfangsverse der Sūrat al-Muddaththir", "Die ganze Sūrat al-Fātiḥa", "Die Anfangsverse der Sūrat al-Baqara"], "Nach der richtigsten Ansicht, gestützt auf den Hadith von ʿĀʾisha bei al-Bukhārī und Muslim, kamen die Anfangsverse von al-ʿAlaq zuerst. Al-Muddaththir und al-Fātiḥa sind andere, schwächere Ansichten."],
    ar: ["ما أول ما نزل من القرآن على القول الأصح؟ (الآية الأولى منه معروضة)", ["صدر سورة العلق", "صدر سورة المدثر", "سورة الفاتحة كاملة", "صدر سورة البقرة"], "الأصح أن أول ما نزل صدر سورة العلق لحديث عائشة في الصحيحين، والقول بالمدثر أو الفاتحة أقوال أخرى أضعف."] },
  { id: "ulr-004", s: "ulum", g: 2, d: 2, t: ["wahy", "definitions"], src: "al-Zarqānī, Manāhil al-ʿIrfān, ch. on revelation",
    en: ["What is the linguistic meaning of waḥy?", ["Swift and hidden communication", "A loud public proclamation", "A written message sent openly", "A long and detailed explanation"], "In the language, waḥy means informing someone in a hidden and swift way (al-iʿlām al-khafī al-sarīʿ). The technical sense is Allah informing a prophet of what He wills."],
    de: ["Was bedeutet waḥy im sprachlichen Sinn?", ["Schnelle und verborgene Mitteilung", "Eine laute öffentliche Verkündung", "Eine offen gesandte schriftliche Botschaft", "Eine lange und ausführliche Erklärung"], "Sprachlich bedeutet waḥy, jemanden verborgen und schnell zu unterrichten (al-iʿlām al-khafī al-sarīʿ). Fachlich ist es Allahs Mitteilung an einen Propheten über das, was Er will."],
    ar: ["ما معنى الوحي في اللغة؟", ["الإعلام الخفي السريع", "الإعلان الجهري العام", "الرسالة المكتوبة المرسلة علنًا", "البيان الطويل المفصل"], "الوحي لغةً الإعلام في خفاء وسرعة، وشرعًا إعلام الله تعالى نبيه بما يريد."] },
  { id: "ulr-005", s: "ulum", g: 2, d: 3, t: ["wahy", "modes-of-revelation"], src: "Ibn Kathīr, Tafsīr, on 42:51", v: "42:51",
    en: ["The verse shown names the ways in which Allah speaks to a human being. Which list matches it?", ["Inspiration, from behind a veil, through a sent messenger", "Inspiration, true dreams, through a sent messenger", "Direct speech, true dreams, from behind a veil", "True dreams, inspiration, an angel in human form"], "The verse names three ways: waḥy in the sense of inspiration, speech from behind a veil, and sending a messenger (an angel) who conveys by Allah's leave. True dreams fall under the first kind but are not named separately."],
    de: ["Der gezeigte Vers nennt die Arten, auf die Allah zu einem Menschen spricht. Welche Liste trifft zu?", ["Eingebung, hinter einem Schleier, durch einen gesandten Boten", "Eingebung, wahre Träume, durch einen gesandten Boten", "Direkte Rede, wahre Träume, hinter einem Schleier", "Wahre Träume, Eingebung, ein Engel in Menschengestalt"], "Der Vers nennt drei Arten: waḥy im Sinne der Eingebung, Rede hinter einem Schleier und das Senden eines Boten (Engels), der mit Allahs Erlaubnis übermittelt. Wahre Träume fallen unter die erste Art, werden aber nicht eigens genannt."],
    ar: ["تذكر الآية المعروضة طرق تكليم الله للبشر. أي قائمة توافقها؟", ["الوحي إلهامًا، ومن وراء حجاب، وإرسال رسول", "الوحي إلهامًا، والرؤيا الصادقة، وإرسال رسول", "التكليم المباشر، والرؤيا الصادقة، ومن وراء حجاب", "الرؤيا الصادقة، والإلهام، وتمثل الملك رجلًا"], "ذكرت الآية ثلاث طرق: الوحي بمعنى الإلقاء في القلب، والتكليم من وراء حجاب، وإرسال رسول من الملائكة يوحي بإذن الله، والرؤيا داخلة في الأول ولم تُذكر مستقلة."] },
  { id: "ulr-006", s: "ulum", g: 2, d: 2, t: ["wahy", "first-revelation"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb Badʾ al-Waḥy",
    en: ["According to ʿĀʾisha in Ṣaḥīḥ al-Bukhārī, how did revelation first begin for the Prophet ﷺ?", ["With true dreams that came like the break of dawn", "With a voice calling him in the marketplace", "With a written page that he found in Ḥirāʾ", "With visions of the angel in the Masjid al-Ḥarām"], "ʿĀʾisha reported that revelation began with true dreams in sleep; every dream he saw came true like the light of dawn. Then seclusion became dear to him and the angel came in Ḥirāʾ."],
    de: ["Womit begann laut ʿĀʾisha in Ṣaḥīḥ al-Bukhārī die Offenbarung für den Propheten ﷺ?", ["Mit wahren Träumen, die wie das Morgengrauen eintrafen", "Mit einer Stimme, die ihn auf dem Markt rief", "Mit einer beschriebenen Seite, die er in Ḥirāʾ fand", "Mit Erscheinungen des Engels in der Masjid al-Ḥarām"], "ʿĀʾisha berichtete, dass die Offenbarung mit wahren Träumen im Schlaf begann; jeder Traum traf ein wie das Licht des Morgens. Danach wurde ihm die Zurückgezogenheit lieb, und der Engel kam in Ḥirāʾ."],
    ar: ["بماذا بُدئ النبي ﷺ من الوحي كما روت عائشة عند البخاري؟", ["بالرؤيا الصادقة تجيء مثل فلق الصبح", "بصوت يناديه في السوق", "بصحيفة مكتوبة وجدها في حراء", "برؤية الملك في المسجد الحرام"], "روت عائشة أن أول ما بُدئ به من الوحي الرؤيا الصادقة في النوم، فكانت كل رؤيا يراها تقع كما رآها واضحة كضوء الصبح، ثم أحب الخلوة فجاءه الملك في حراء."] },
  { id: "ulr-007", s: "ulum", g: 2, d: 3, t: ["wahy", "modes-of-revelation"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb Badʾ al-Waḥy",
    en: ["When al-Ḥārith ibn Hishām asked how the revelation came, which mode did the Prophet ﷺ describe as the hardest on him?", ["When it came like the ringing of a bell", "When the angel came in the form of a man", "When it came in a dream during sleep", "When it was cast into his heart"], "In the hadith of ʿĀʾisha in al-Bukhārī, the Prophet ﷺ said it sometimes came like the ringing of a bell (ṣalṣalat al-jaras), which was the hardest on him; at other times the angel came as a man and spoke to him."],
    de: ["Als al-Ḥārith ibn Hishām fragte, wie die Offenbarung komme, welche Art beschrieb der Prophet ﷺ als die schwerste für ihn?", ["Wenn sie wie das Läuten einer Glocke kam", "Wenn der Engel in Gestalt eines Mannes kam", "Wenn sie im Traum während des Schlafes kam", "Wenn sie ihm ins Herz gelegt wurde"], "Im Hadith von ʿĀʾisha bei al-Bukhārī sagte der Prophet ﷺ, sie komme manchmal wie das Läuten einer Glocke (ṣalṣalat al-jaras), und das sei für ihn am schwersten; manchmal komme der Engel als Mann und spreche zu ihm."],
    ar: ["لما سأل الحارث بن هشام عن كيفية الوحي، أيُّ حال وصفها النبي ﷺ بأنها أشد عليه؟", ["أن يأتيه مثل صلصلة الجرس", "أن يتمثل له الملك رجلًا", "أن يأتيه رؤيا في المنام", "أن يُلقى في قلبه"], "في حديث عائشة عند البخاري أخبر النبي ﷺ أن الوحي يأتيه أحيانًا في صورة صوت كصلصلة الجرس وهي أشد الأحوال عليه، وأحيانًا يأتيه الملك في صورة رجل فيكلمه."] },
  { id: "ulr-008", s: "ulum", g: 2, d: 2, t: ["wahy", "modes-of-revelation"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb Badʾ al-Waḥy",
    en: ["What did ʿĀʾisha report seeing when revelation came to the Prophet ﷺ on a very cold day?", ["His forehead streaming with sweat", "His face turning pale and cold", "Him falling asleep at once", "His voice becoming very loud"], "ʿĀʾisha said she saw the revelation come to him on an intensely cold day, and when it left him his forehead was dripping with sweat. This shows the weight of receiving revelation."],
    de: ["Was sah ʿĀʾisha nach ihrem Bericht, wenn die Offenbarung an einem sehr kalten Tag zum Propheten ﷺ kam?", ["Seine Stirn triefte vor Schweiß", "Sein Gesicht wurde blass und kalt", "Er schlief sofort ein", "Seine Stimme wurde sehr laut"], "ʿĀʾisha sagte, sie habe gesehen, wie die Offenbarung an einem sehr kalten Tag zu ihm kam, und wenn sie endete, tropfte seine Stirn vor Schweiß. Das zeigt die Schwere des Offenbarungsempfangs."],
    ar: ["ماذا روت عائشة أنها رأت حين ينزل الوحي على النبي ﷺ في اليوم الشديد البرد؟", ["جبينه يتفصّد عرقًا", "وجهه يصفرّ ويبرد", "يغلبه النوم في الحال", "صوته يرتفع جدًّا"], "أخبرت عائشة أنها رأت الوحي ينزل عليه في يوم شديد البرد، فإذا انقضى كان العرق يسيل من جبينه، وفي ذلك بيان ثقل الوحي."] },
  { id: "ulr-009", s: "ulum", g: 3, d: 3, t: ["wahy", "modes-of-revelation"], src: "Ibn Kathīr, Tafsīr, on 42:51 and 4:164", v: "4:164",
    en: ["The verse shown describes Allah speaking to Mūsā. Under which of the modes named in 42:51 does this fall?", ["Speech from behind a veil", "Inspiration cast into the heart", "Sending an angel as messenger", "A true dream in sleep"], "Allah spoke to Mūsā directly, without an angel in between, yet Mūsā did not see Him. Scholars therefore place it under speech from behind a veil, as in the Prophet's ﷺ experience during the Miʿrāj."],
    de: ["Der gezeigte Vers beschreibt, wie Allah zu Mūsā sprach. Unter welche der in 42:51 genannten Arten fällt das?", ["Rede hinter einem Schleier", "Eingebung ins Herz", "Senden eines Engels als Boten", "Ein wahrer Traum im Schlaf"], "Allah sprach direkt zu Mūsā, ohne vermittelnden Engel, doch Mūsā sah Ihn nicht. Daher ordnen die Gelehrten es der Rede hinter einem Schleier zu, wie auch das Erleben des Propheten ﷺ beim Miʿrāj."],
    ar: ["تذكر الآية المعروضة تكليم الله لموسى. تحت أي طريق من طرق آية الشورى (42:51) يندرج؟", ["التكليم من وراء حجاب", "الإلقاء في القلب", "إرسال الملك رسولًا", "الرؤيا في المنام"], "كلّم الله موسى بلا واسطة ملك ولم يره، فجعله العلماء من التكليم من وراء حجاب، ومثله ما كان للنبي ﷺ ليلة المعراج."] },
  { id: "ulr-010", s: "ulum", g: 2, d: 3, t: ["wahy", "definitions"], src: "Ibn Kathīr, Tafsīr, on 16:68", v: "16:68",
    en: ["In the verse shown, waḥy is used for the bee. What does it mean here?", ["Instinctive guidance placed in a creature", "Prophetic revelation through an angel", "A command conveyed by a prophet", "A true dream seen in sleep"], "The verse uses waḥy in its linguistic sense: Allah guided the bee by instinct to build its dwellings and gather food. It is not revelation in the technical sense given to prophets."],
    de: ["Im gezeigten Vers wird waḥy für die Biene gebraucht. Was bedeutet es hier?", ["In ein Geschöpf gelegte instinktive Leitung", "Prophetische Offenbarung durch einen Engel", "Ein durch einen Propheten übermittelter Befehl", "Ein wahrer Traum im Schlaf"], "Der Vers gebraucht waḥy im sprachlichen Sinn: Allah leitete die Biene durch Instinkt an, Wohnstätten zu bauen und Nahrung zu sammeln. Das ist keine Offenbarung im fachlichen Sinn, wie sie Propheten erhalten."],
    ar: ["وردت كلمة الوحي في الآية المعروضة في شأن النحل. ما معناها هنا؟", ["الإلهام الغريزي المجعول في المخلوق", "الوحي النبوي بواسطة الملك", "الأمر المبلَّغ على لسان نبي", "الرؤيا الصادقة في المنام"], "الوحي هنا بمعناه اللغوي، أي الإلهام الفطري الذي هدى الله به النحل إلى اتخاذ البيوت وجمع الطعام، وليس الوحي الشرعي الخاص بالأنبياء."] },
  { id: "ulr-011", s: "ulum", g: 2, d: 2, t: ["wahy", "jibril"], src: "Ibn Kathīr, Tafsīr, on 26:193", v: "26:193", w: 3,
    en: ["The highlighted word, together with the word after it, is a title. To whom does it refer?", ["Jibrīl", "The Prophet ﷺ", "Mūsā", "Mīkāʾīl"], "The 'trustworthy spirit' (al-rūḥ al-amīn) who brought the Quran down upon the Prophet's ﷺ heart is Jibrīl, by agreement of the exegetes."],
    de: ["Das markierte Wort bildet mit dem folgenden einen Beinamen. Auf wen bezieht er sich?", ["Jibrīl", "Den Propheten ﷺ", "Mūsā", "Mīkāʾīl"], "Der „vertrauenswürdige Geist“ (al-rūḥ al-amīn), der den Koran auf das Herz des Propheten ﷺ herabbrachte, ist nach Übereinstimmung der Exegeten Jibrīl."],
    ar: ["الكلمة المظللة مع التي بعدها لقبٌ. على مَن يدل؟", ["جبريل", "النبي ﷺ", "موسى", "ميكائيل"], "الروح الأمين الذي نزل بالقرآن على قلب النبي ﷺ هو جبريل عليه السلام باتفاق المفسرين."] },
  { id: "ulr-012", s: "ulum", g: 4, d: 5, t: ["wahy", "modes-of-revelation"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Ṣalāt; al-Suyūṭī, al-Itqān, ch. on how the revelation descended",
    en: ["Which surah is linked to the report of Anas in Ṣaḥīḥ Muslim in which the Prophet ﷺ raised his head smiling after a brief doze (ighfāʾa) and recited a surah just revealed to him?", ["Sūrat al-Kawthar", "Sūrat al-Ikhlāṣ", "Sūrat al-Ḍuḥā", "Sūrat al-Sharḥ"], "The report concerns al-Kawthar. Some took it as revelation during sleep, while al-Suyūṭī and others explained the 'doze' as the state that came over him when revelation descended, so the principle that the whole Quran came through Jibrīl while awake remains."],
    de: ["Welche Sure ist mit dem Bericht von Anas in Ṣaḥīḥ Muslim verbunden, in dem der Prophet ﷺ nach kurzem Einnicken (ighfāʾa) lächelnd den Kopf hob und eine soeben offenbarte Sure rezitierte?", ["Sūrat al-Kawthar", "Sūrat al-Ikhlāṣ", "Sūrat al-Ḍuḥā", "Sūrat al-Sharḥ"], "Der Bericht betrifft al-Kawthar. Manche verstanden ihn als Offenbarung im Schlaf, während al-Suyūṭī und andere das „Einnicken“ als den Zustand erklärten, der ihn beim Herabkommen der Offenbarung überkam; so bleibt der Grundsatz bestehen, dass der ganze Koran im Wachzustand durch Jibrīl kam."],
    ar: ["أيّ سورة يتعلق بها حديث أنس في صحيح مسلم أن النبي ﷺ أغفى إغفاءة ثم رفع رأسه متبسمًا وقرأ سورة أُنزلت عليه آنفًا؟", ["سورة الكوثر", "سورة الإخلاص", "سورة الضحى", "سورة الشرح"], "الحديث في سورة الكوثر، فحمله بعضهم على نزولها في المنام، وحمل السيوطي وغيره الإغفاءة على الحال التي كانت تعتريه عند الوحي، فيبقى أن القرآن كله نزل به جبريل يقظةً."] },
  { id: "ulr-013", s: "ulum", g: 2, d: 3, t: ["wahy", "jibril"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb Faḍāʾil al-Qurʾān, chapter on Jibrīl reviewing the Quran",
    en: ["Jibrīl used to review the Quran with the Prophet ﷺ each Ramadan. What was different in the year of his death?", ["He reviewed it with him twice", "He reviewed it with him three times", "There was no review that year", "The review took place in Shaʿbān"], "Al-Bukhārī reports that Jibrīl reviewed the Quran with him once every year, and twice in the year he passed away; the Prophet ﷺ understood this as a sign that his death was near."],
    de: ["Jibrīl ging den Koran jeden Ramaḍān mit dem Propheten ﷺ durch. Was war im Jahr seines Todes anders?", ["Er ging ihn zweimal mit ihm durch", "Er ging ihn dreimal mit ihm durch", "In jenem Jahr fand keine Durchsicht statt", "Die Durchsicht fand im Shaʿbān statt"], "Al-Bukhārī berichtet, dass Jibrīl den Koran jedes Jahr einmal mit ihm durchging und im Jahr seines Todes zweimal; der Prophet ﷺ verstand dies als Zeichen, dass sein Tod nahe war."],
    ar: ["كان جبريل يعارض النبي ﷺ القرآن في كل رمضان. فما الذي اختلف في العام الذي توفي فيه؟", ["عارضه به مرتين", "عارضه به ثلاث مرات", "لم تكن معارضة ذلك العام", "كانت المعارضة في شعبان"], "روى البخاري أن جبريل كان يعارضه القرآن كل عام مرة، وعارضه في العام الذي قُبض فيه مرتين، ففهم النبي ﷺ من ذلك قرب أجله."] },

  // ---------- first and last revelations ----------
  { id: "ulr-014", s: "ulum", g: 2, d: 3, t: ["first-revelation", "wahy"], src: "Ibn Ḥajar, Fatḥ al-Bārī, Kitāb Badʾ al-Waḥy",
    en: ["What is meant by fatrat al-waḥy?", ["A temporary pause in revelation after the first revelation", "The period between the hijra and the battle of Badr", "The night on which the whole Quran descended", "The years in which only Medinan verses were revealed"], "Fatrat al-waḥy is the pause after the first verses of al-ʿAlaq during which no revelation came, until the angel appeared again and the opening of al-Muddaththir was revealed."],
    de: ["Was ist mit fatrat al-waḥy gemeint?", ["Eine vorübergehende Unterbrechung der Offenbarung nach der ersten Offenbarung", "Der Zeitraum zwischen der Hidschra und der Schlacht von Badr", "Die Nacht, in der der ganze Koran herabkam", "Die Jahre, in denen nur medinensische Verse offenbart wurden"], "Fatrat al-waḥy ist die Pause nach den ersten Versen von al-ʿAlaq, in der keine Offenbarung kam, bis der Engel wieder erschien und der Anfang von al-Muddaththir offenbart wurde."],
    ar: ["ما المقصود بفترة الوحي؟", ["انقطاع الوحي مدةً بعد أول نزوله", "المدة بين الهجرة وغزوة بدر", "الليلة التي نزل فيها القرآن جملة", "السنوات التي لم ينزل فيها إلا المدني"], "فترة الوحي هي انقطاعه مدة بعد نزول صدر سورة العلق، حتى رأى النبي ﷺ الملك مرة أخرى فنزل صدر سورة المدثر."] },
  { id: "ulr-015", s: "ulum", g: 3, d: 4, t: ["first-revelation"], src: "al-Suyūṭī, al-Itqān, ch. on the first revelation; al-Bukhārī, Kitāb al-Tafsīr, Sūrat al-Muddaththir", v: "74:1",
    en: ["Jābir's report in al-Bukhārī and Muslim names the surah shown as the first revealed. How do most scholars reconcile this with the report of ʿĀʾisha?", ["Al-Muddaththir was the first revealed after the pause in revelation", "Al-ʿAlaq came in a dream, al-Muddaththir while awake", "Jābir's report is weak and is set aside", "Both surahs were revealed in full on the same day"], "Jābir's own wording mentions the angel 'who had come to me in Ḥirāʾ', so al-Muddaththir came after al-ʿAlaq. Scholars therefore say al-ʿAlaq was absolutely first, and al-Muddaththir first after the fatra, or first in commanding him to warn."],
    de: ["Jābirs Bericht bei al-Bukhārī und Muslim nennt die gezeigte Sure als zuerst offenbart. Wie bringen die meisten Gelehrten dies mit dem Bericht von ʿĀʾisha in Einklang?", ["Al-Muddaththir war das Erste nach der Unterbrechung der Offenbarung", "Al-ʿAlaq kam im Traum, al-Muddaththir im Wachzustand", "Jābirs Bericht ist schwach und wird beiseitegelassen", "Beide Suren wurden am selben Tag vollständig offenbart"], "Jābirs eigener Wortlaut erwähnt den Engel, „der in Ḥirāʾ zu mir gekommen war“; al-Muddaththir kam also nach al-ʿAlaq. Daher sagen die Gelehrten, al-ʿAlaq sei absolut das Erste, al-Muddaththir das Erste nach der fatra oder das Erste mit dem Auftrag zu warnen."],
    ar: ["في حديث جابر في الصحيحين أن السورة المعروضة أول ما نزل. كيف جمع أكثر العلماء بينه وبين حديث عائشة؟", ["المدثر أول ما نزل بعد فترة الوحي", "العلق نزلت منامًا والمدثر يقظةً", "حديث جابر ضعيف فيُطرح", "نزلت السورتان كاملتين في يوم واحد"], "في لفظ جابر نفسه ذكر الملك الذي جاءه بحراء، فدلّ على أن المدثر نزلت بعد العلق، فالعلق أول ما نزل مطلقًا، والمدثر أول ما نزل بعد فترة الوحي أو أول ما نزل في الأمر بالإنذار."] },
  { id: "ulr-016", s: "ulum", g: 2, d: 3, t: ["last-revelation", "meccan-medinan"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Īmān, report of ʿUmar on 5:3", v: "5:3",
    en: ["According to ʿUmar's report in al-Bukhārī, where was the passage on the perfection of the religion in the verse shown revealed?", ["At ʿArafa during the Farewell Pilgrimage", "In Mecca on the day of the conquest", "In Medina during his final illness", "At al-Ḥudaybiya after the treaty"], "ʿUmar said he knew the day and place: it was revealed on the day of ʿArafa, a Friday, while the Prophet ﷺ was standing at ʿArafa in the Farewell Pilgrimage."],
    de: ["Wo wurde laut dem Bericht von ʿUmar bei al-Bukhārī die Stelle über die Vollendung der Religion im gezeigten Vers offenbart?", ["In ʿArafa während der Abschiedswallfahrt", "In Mekka am Tag der Eroberung", "In Medina während seiner letzten Krankheit", "In al-Ḥudaybiya nach dem Vertrag"], "ʿUmar sagte, er kenne Tag und Ort: Sie wurde am Tag von ʿArafa, einem Freitag, offenbart, als der Prophet ﷺ während der Abschiedswallfahrt in ʿArafa stand."],
    ar: ["بحسب رواية عمر عند البخاري، أين نزل موضع إكمال الدين في الآية المعروضة؟", ["بعرفة في حجة الوداع", "بمكة يوم الفتح", "بالمدينة في مرض موته", "بالحديبية بعد الصلح"], "أخبر عمر أنه يعرف يوم نزولها ومكانه: نزلت يوم عرفة وكان يوم جمعة، والنبي ﷺ واقف بعرفة في حجة الوداع."] },
  { id: "ulr-017", s: "ulum", g: 4, d: 4, t: ["last-revelation"], src: "al-Suyūṭī, al-Itqān, ch. on the last revelation (report of al-Nasāʾī)", v: "2:281",
    en: ["According to a report from Ibn ʿAbbās transmitted by al-Nasāʾī, what distinction does the verse shown have?", ["It was the last verse of the Quran revealed", "It was the first verse revealed in Medina", "It was revealed at ʿArafa in the Farewell Pilgrimage", "It was revealed twice, in Mecca and in Medina"], "Al-Nasāʾī transmits from ʿIkrima that Ibn ʿAbbās said the last thing revealed of the Quran was this verse about the day of return to Allah. Al-Suyūṭī lists it among the main views on the last revelation."],
    de: ["Welche Besonderheit hat der gezeigte Vers nach einem Bericht von Ibn ʿAbbās, den al-Nasāʾī überliefert?", ["Er war der zuletzt offenbarte Vers des Korans", "Er war der erste in Medina offenbarte Vers", "Er wurde in ʿArafa bei der Abschiedswallfahrt offenbart", "Er wurde zweimal offenbart, in Mekka und in Medina"], "Al-Nasāʾī überliefert von ʿIkrima, dass Ibn ʿAbbās sagte, das Letzte, was vom Koran offenbart wurde, sei dieser Vers über den Tag der Rückkehr zu Allah. Al-Suyūṭī führt ihn unter den Hauptansichten zur letzten Offenbarung auf."],
    ar: ["ما الذي امتازت به الآية المعروضة في رواية عن ابن عباس أخرجها النسائي؟", ["أنها آخر ما نزل من القرآن", "أنها أول آية نزلت بالمدينة", "أنها نزلت بعرفة في حجة الوداع", "أنها نزلت مرتين بمكة والمدينة"], "روى النسائي من طريق عكرمة عن ابن عباس أن هذه الآية كانت آخر ما نزل من القرآن، وهي في التذكير بيوم الرجوع إلى الله، وعدّها السيوطي من أشهر الأقوال في آخر ما نزل."] },
  { id: "ulr-018", s: "ulum", g: 4, d: 4, t: ["last-revelation"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Tafsīr, Sūrat al-Nisāʾ", v: "4:176",
    en: ["In Ṣaḥīḥ al-Bukhārī, al-Barāʾ ibn ʿĀzib names the verse shown as the last verse revealed. Which surah does he name as the last surah revealed?", ["Barāʾa (al-Tawba)", "Al-Naṣr", "Al-Māʾida", "Al-Baqara"], "Al-Barāʾ said the last surah revealed was Barāʾa and the last verse the kalāla verse at the end of al-Nisāʾ. Other Companions named other passages; scholars hold each reported what he last knew."],
    de: ["In Ṣaḥīḥ al-Bukhārī nennt al-Barāʾ ibn ʿĀzib den gezeigten Vers als den zuletzt offenbarten Vers. Welche Sure nennt er als die zuletzt offenbarte Sure?", ["Barāʾa (al-Tawba)", "Al-Naṣr", "Al-Māʾida", "Al-Baqara"], "Al-Barāʾ sagte, die zuletzt offenbarte Sure sei Barāʾa und der letzte Vers der kalāla-Vers am Ende von al-Nisāʾ. Andere Gefährten nannten andere Stellen; die Gelehrten meinen, jeder habe berichtet, was er zuletzt kannte."],
    ar: ["في صحيح البخاري ذكر البراء بن عازب أن الآية المعروضة آخر آية نزلت. فما السورة التي ذكر أنها آخر سورة نزلت؟", ["براءة (التوبة)", "النصر", "المائدة", "البقرة"], "أخبر البراء أن سورة براءة آخر السور نزولًا، وأن آية الكلالة في خاتمة النساء آخر الآيات نزولًا، وذكر غيره من الصحابة غير ذلك، وحمله العلماء على أن كلًّا أخبر بما انتهى إليه علمه."] },
  { id: "ulr-019", s: "ulum", g: 3, d: 4, t: ["last-revelation"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Tafsīr",
    en: ["According to Ibn ʿAbbās in Ṣaḥīḥ Muslim, which was the last surah revealed complete at one time?", ["Al-Naṣr", "Al-Kawthar", "Al-Ikhlāṣ", "Al-Tawba"], "Ibn ʿAbbās asked ʿUbaydullāh ibn ʿAbdillāh whether he knew the last surah revealed all together, and named al-Naṣr. The qualifier 'complete at one time' distinguishes this from reports about the last verse."],
    de: ["Welche Sure war laut Ibn ʿAbbās in Ṣaḥīḥ Muslim die letzte, die vollständig auf einmal offenbart wurde?", ["Al-Naṣr", "Al-Kawthar", "Al-Ikhlāṣ", "Al-Tawba"], "Ibn ʿAbbās fragte ʿUbaydullāh ibn ʿAbdillāh, ob er die letzte vollständig auf einmal offenbarte Sure kenne, und nannte al-Naṣr. Der Zusatz „vollständig auf einmal“ unterscheidet dies von den Berichten über den letzten Vers."],
    ar: ["بحسب قول ابن عباس في صحيح مسلم، ما آخر سورة نزلت من القرآن جميعًا؟", ["النصر", "الكوثر", "الإخلاص", "التوبة"], "سأل ابن عباس عبيدَ الله بن عبد الله عن آخر سورة نزلت كاملة دفعة واحدة، ثم ذكر أنها سورة النصر، وقيد «جميعًا» يفرّق بينه وبين الروايات في آخر آية."] },
  { id: "ulr-020", s: "ulum", g: 4, d: 5, t: ["last-revelation"], src: "al-Suyūṭī, al-Itqān, ch. on the last revelation (citing al-Qāḍī Abū Bakr al-Bāqillānī, al-Intiṣār)",
    en: ["How does al-Qāḍī Abū Bakr al-Bāqillānī, cited by al-Suyūṭī, explain the differing reports on the last revelation?", ["None is attributed to the Prophet ﷺ; each Companion spoke from his own judgment or what he last heard", "One report is authentic and the others are fabricated", "The Prophet ﷺ himself named several verses as the last", "The reports refer to different modes of recitation"], "Al-Bāqillānī noted that none of these statements is raised to the Prophet ﷺ; each Companion said it by ijtihād and strong likelihood, possibly reporting the last thing he heard from him. This removes the apparent contradiction."],
    de: ["Wie erklärt al-Qāḍī Abū Bakr al-Bāqillānī, zitiert bei al-Suyūṭī, die abweichenden Berichte über die letzte Offenbarung?", ["Keiner wird dem Propheten ﷺ zugeschrieben; jeder Gefährte sprach nach eigenem Urteil oder nach dem, was er zuletzt hörte", "Ein Bericht ist authentisch, die anderen sind erfunden", "Der Prophet ﷺ selbst nannte mehrere Verse als die letzten", "Die Berichte beziehen sich auf verschiedene Lesarten"], "Al-Bāqillānī stellte fest, dass keine dieser Aussagen auf den Propheten ﷺ zurückgeführt wird; jeder Gefährte sprach aus ijtihād und starker Vermutung, womöglich über das Letzte, das er von ihm hörte. So löst sich der scheinbare Widerspruch."],
    ar: ["كيف وجّه القاضي أبو بكر الباقلاني، فيما نقله السيوطي، اختلاف الروايات في آخر ما نزل؟", ["ليس شيء منها مرفوعًا، وكلٌّ قاله باجتهاده أو بحسب آخر ما سمع", "إحداها صحيحة والباقي موضوع", "النبي ﷺ نفسه سمّى عدة آيات آخرًا", "الروايات راجعة إلى اختلاف القراءات"], "بيّن الباقلاني أن هذه الأقوال لم يُرفع شيء منها إلى النبي ﷺ، وإنما قالها كل صحابي باجتهاده وغالب ظنه، وربما أخبر كلٌّ بآخر ما سمعه منه، فيزول التعارض."] },

  // ---------- gradual revelation (tanjīm) ----------
  { id: "ulr-021", s: "ulum", g: 1, d: 1, t: ["tanjim"], src: "al-Suyūṭī, al-Itqān, ch. on how the revelation descended",
    en: ["Over roughly how many years was the Quran revealed, as commonly stated?", ["About 23 years", "About 10 years", "About 40 years", "About 13 years"], "The Quran came down in portions from the start of the mission until shortly before the Prophet's ﷺ death, commonly stated as about 23 years: about 13 in Mecca and 10 in Medina."],
    de: ["Über wie viele Jahre wurde der Koran nach der üblichen Angabe offenbart?", ["Etwa 23 Jahre", "Etwa 10 Jahre", "Etwa 40 Jahre", "Etwa 13 Jahre"], "Der Koran kam vom Beginn der Sendung bis kurz vor dem Tod des Propheten ﷺ in Teilen herab, üblicherweise mit etwa 23 Jahren angegeben: etwa 13 in Mekka und 10 in Medina."],
    ar: ["في كم سنة تقريبًا نزل القرآن على المشهور؟", ["نحو ثلاث وعشرين سنة", "نحو عشر سنين", "نحو أربعين سنة", "نحو ثلاث عشرة سنة"], "نزل القرآن منجمًا من أول البعثة إلى قُبيل وفاة النبي ﷺ، والمشهور نحو ثلاث وعشرين سنة: قرابة ثلاث عشرة بمكة وعشر بالمدينة."] },
  { id: "ulr-022", s: "ulum", g: 1, d: 2, t: ["tanjim", "definitions"], src: "al-Zarqānī, Manāhil al-ʿIrfān, ch. on the descent of the Quran",
    en: ["What does tanjīm al-Qurʾān mean?", ["Revealing the Quran in portions over time", "Arranging the surahs by length", "Counting the verses of each surah", "Writing the Quran with vowel marks"], "Tanjīm means that the Quran was sent down in separate portions according to events and needs, not all at once. The word comes from najm, an instalment."],
    de: ["Was bedeutet tanjīm al-Qurʾān?", ["Die Offenbarung des Korans in Teilen über eine Zeitspanne", "Die Anordnung der Suren nach ihrer Länge", "Das Zählen der Verse jeder Sure", "Das Schreiben des Korans mit Vokalzeichen"], "Tanjīm bedeutet, dass der Koran in getrennten Teilen nach Ereignissen und Bedürfnissen herabgesandt wurde, nicht auf einmal. Das Wort kommt von najm, einer Rate."],
    ar: ["ما معنى تنجيم القرآن؟", ["نزوله مفرَّقًا على مدة من الزمن", "ترتيب السور بحسب طولها", "عدّ آيات كل سورة", "كتابة المصحف بالشكل"], "التنجيم أن ينزل القرآن أجزاء متفرقة بحسب الوقائع والحاجات لا جملة واحدة، مأخوذ من النجم بمعنى القسط."] },
  { id: "ulr-023", s: "ulum", g: 2, d: 2, t: ["tanjim"], src: "Ibn Kathīr, Tafsīr, on 25:32", v: "25:32",
    en: ["The disbelievers asked why the Quran was not sent down all at once. Which wisdom does the verse shown give in reply?", ["To make firm the Prophet's ﷺ heart", "To test the angels' obedience", "To allow the scribes time to buy materials", "To match the length of earlier scriptures"], "The verse answers that it was revealed in parts to strengthen the Prophet's ﷺ heart and was recited in measured order. Repeated revelation renewed his support at every stage of the call."],
    de: ["Die Ungläubigen fragten, warum der Koran nicht auf einmal herabgesandt wurde. Welche Weisheit nennt der gezeigte Vers als Antwort?", ["Das Herz des Propheten ﷺ zu festigen", "Den Gehorsam der Engel zu prüfen", "Den Schreibern Zeit zum Kauf von Material zu geben", "Der Länge früherer Schriften zu entsprechen"], "Der Vers antwortet, dass er in Teilen offenbart wurde, um das Herz des Propheten ﷺ zu festigen, und in wohlgeordneter Folge vorgetragen wurde. Die wiederholte Offenbarung erneuerte seine Stärkung in jeder Phase."],
    ar: ["سأل الكفار: لماذا لم ينزل القرآن جملة واحدة؟ فما الحكمة التي ذكرتها الآية المعروضة جوابًا؟", ["تثبيت فؤاد النبي ﷺ", "اختبار طاعة الملائكة", "إمهال الكتبة لشراء الأدوات", "موافقة طول الكتب السابقة"], "أجابت الآية بأن تنزيله مفرقًا لتثبيت فؤاد النبي ﷺ، ورُتّل ترتيلًا، فكان تجدّد الوحي تقويةً له في كل مرحلة من الدعوة."] },
  { id: "ulr-024", s: "ulum", g: 2, d: 3, t: ["tanjim"], src: "Ibn Kathīr, Tafsīr, on 17:106", v: "17:106", w: 7,
    en: ["What does the highlighted word, together with the word before it, express about the revelation?", ["That it was recited to people at a measured pace", "That it was hidden from people for a time", "That it was revealed only at night", "That it was written before it was recited"], "The phrase means 'with deliberation': the Quran was divided into parts so that the Prophet ﷺ would recite it to people slowly and at intervals, making it easier to understand and memorise."],
    de: ["Was drückt das markierte Wort zusammen mit dem Wort davor über die Offenbarung aus?", ["Dass sie den Menschen in bedachtem Tempo vorgetragen wurde", "Dass sie den Menschen eine Zeit lang verborgen blieb", "Dass sie nur nachts offenbart wurde", "Dass sie aufgeschrieben wurde, bevor sie vorgetragen wurde"], "Die Wendung bedeutet „mit Bedacht“: Der Koran wurde in Teile gegliedert, damit der Prophet ﷺ ihn den Menschen langsam und in Abständen vortrage, was Verstehen und Auswendiglernen erleichtert."],
    ar: ["ماذا تفيد الكلمة المظللة مع التي قبلها في شأن الوحي؟", ["أنه يُقرأ على الناس على تؤدة ومهل", "أنه أُخفي عن الناس مدة", "أنه لم ينزل إلا ليلًا", "أنه كُتب قبل أن يُقرأ"], "المعنى: على تمهل وتؤدة، فقد فُرّق القرآن ليقرأه النبي ﷺ على الناس شيئًا بعد شيء، فيسهل فهمه وحفظه."] },
  { id: "ulr-025", s: "ulum", g: 2, d: 3, t: ["tanjim", "gradual-legislation"], src: "Ibn Kathīr, Tafsīr, on 2:219, 4:43 and 5:90", v: "5:90",
    en: ["In the well-known stages by which wine was forbidden, what role does the verse shown play?", ["It is the final, decisive prohibition", "It first mentions both harm and benefit", "It forbids approaching prayer while intoxicated", "It mentions intoxicants among Allah's provisions"], "Scholars cite wine as the classic example of gradual legislation: 2:219 mentions harm outweighing benefit, 4:43 forbids prayer while intoxicated, and 5:90–91 make the prohibition final."],
    de: ["Welche Rolle spielt der gezeigte Vers in den bekannten Stufen des Weinverbots?", ["Er ist das endgültige, entscheidende Verbot", "Er erwähnt erstmals Schaden und Nutzen", "Er verbietet, sich dem Gebet berauscht zu nähern", "Er erwähnt Berauschendes unter Allahs Gaben"], "Die Gelehrten nennen den Wein als klassisches Beispiel stufenweiser Gesetzgebung: 2:219 erwähnt, dass der Schaden den Nutzen überwiegt, 4:43 verbietet das Gebet im Rausch, und 5:90–91 machen das Verbot endgültig."],
    ar: ["في مراحل تحريم الخمر المشهورة، ما دور الآية المعروضة؟", ["التحريم القاطع الأخير", "أول ذكر للإثم والمنفعة", "النهي عن قربان الصلاة حال السكر", "ذكر المسكر في سياق النعم"], "يُمثَّل بالخمر للتدرج في التشريع: آية البقرة (2:219) ذكرت أن إثمها أكبر من نفعها، وآية النساء (4:43) نهت عن الصلاة حال السكر، ثم جاءت آيتا المائدة (5:90–91) بالتحريم القاطع."] },
  { id: "ulr-026", s: "ulum", g: 3, d: 3, t: ["tanjim", "gradual-legislation"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb Faḍāʾil al-Qurʾān, chapter on the arrangement of the Quran (taʾlīf al-Qurʾān)",
    en: ["ʿĀʾisha said, in al-Bukhārī, that the first revealed were surahs of the mufaṣṣal mentioning Paradise and the Fire, and only later rulings on lawful and unlawful. Which wisdom of tanjīm does this show?", ["Faith was established in hearts before laws were imposed", "Short surahs were easier for the scribes to write", "Rulings were kept secret until Medina", "The Quran followed the order of the earlier scriptures"], "She added that had the prohibition of wine come first, people would have refused to give it up. Gradual revelation first built belief in Allah and the Hereafter, so that later commands were accepted."],
    de: ["ʿĀʾisha sagte bei al-Bukhārī, zuerst seien Suren des mufaṣṣal offenbart worden, die Paradies und Feuer erwähnen, und erst später Regeln über Erlaubtes und Verbotenes. Welche Weisheit des tanjīm zeigt das?", ["Der Glaube wurde in den Herzen gefestigt, bevor Gesetze auferlegt wurden", "Kurze Suren waren für die Schreiber leichter zu schreiben", "Die Regeln wurden bis Medina geheim gehalten", "Der Koran folgte der Reihenfolge früherer Schriften"], "Sie fügte hinzu: Wäre das Weinverbot zuerst gekommen, hätten die Menschen sich geweigert, davon zu lassen. Die stufenweise Offenbarung festigte zuerst den Glauben an Allah und das Jenseits, damit spätere Gebote angenommen wurden."],
    ar: ["قالت عائشة فيما رواه البخاري: إن أول ما نزل سور من المفصل فيها ذكر الجنة والنار، ثم نزل الحلال والحرام. أي حكمة للتنجيم يبيّنها ذلك؟", ["ترسيخ الإيمان في القلوب قبل فرض الأحكام", "سهولة كتابة السور القصار على الكتبة", "كتمان الأحكام إلى أن تكون الهجرة", "اتباع ترتيب الكتب السابقة"], "وذكرت أنه لو نزل النهي عن شرب الخمر أولًا لامتنع الناس من تركها، فالتدرج بنى الإيمان بالله واليوم الآخر أولًا لتُقبل الأوامر بعد ذلك."] },
  { id: "ulr-027", s: "ulum", g: 3, d: 4, t: ["tanjim", "asbab-al-nuzul"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Tafsīr, Sūrat al-Nisāʾ (report of Zayd ibn Thābit)", v: "4:95", w: 6,
    en: ["The highlighted word begins a phrase that, per Zayd ibn Thābit in al-Bukhārī, was revealed separately after the rest of the passage. What occasioned it?", ["The complaint of Ibn Umm Maktūm about his blindness", "Kaʿb ibn Mālik staying behind from Tabūk", "The excuses of the hypocrites before Uḥud", "The lameness of ʿAmr ibn al-Jamūḥ"], "When the verse on the inequality of those who stay behind was dictated, Ibn Umm Maktūm, who was blind, raised his excuse, and the exemption for those with disability came down. It shows that a revelation could be as short as part of a verse."],
    de: ["Das markierte Wort leitet eine Wendung ein, die laut Zayd ibn Thābit bei al-Bukhārī nach dem Rest der Stelle gesondert offenbart wurde. Was war der Anlass?", ["Die Klage von Ibn Umm Maktūm über seine Blindheit", "Das Zurückbleiben von Kaʿb ibn Mālik bei Tabūk", "Die Ausreden der Heuchler vor Uḥud", "Die Lahmheit von ʿAmr ibn al-Jamūḥ"], "Als der Vers über die Ungleichheit der Zurückbleibenden diktiert wurde, brachte der blinde Ibn Umm Maktūm seine Entschuldigung vor, und die Ausnahme für Menschen mit Beeinträchtigung kam herab. Das zeigt, dass eine Offenbarung so kurz wie ein Teil eines Verses sein konnte."],
    ar: ["الكلمة المظللة أول عبارة نزلت مستقلة بعد سائر الآية كما روى زيد بن ثابت عند البخاري. ما سبب نزولها؟", ["شكوى ابن أم مكتوم من عماه", "تخلّف كعب بن مالك عن تبوك", "أعذار المنافقين قبل أحد", "عرج عمرو بن الجموح"], "لما أُملي على زيد صدر الآية في عدم استواء القاعدين، شكا ابن أم مكتوم عماه فنزل استثناء أولي الضرر، وفيه أن النازل قد يكون بعض آية."] },
  { id: "ulr-028", s: "ulum", g: 3, d: 3, t: ["tanjim"], src: "al-Zarqānī, Manāhil al-ʿIrfān, ch. on the wisdom of gradual revelation",
    en: ["Passages in which the Quran answers questions people put to the Prophet ﷺ (the yasʾalūnaka passages) illustrate which wisdom of gradual revelation?", ["Answering questions and events as they arose", "Hiding rulings until the community was larger", "Matching the order of revelation to the order of the muṣḥaf", "Testing the scribes' speed in writing"], "Many verses came in response to a question or an event at the time it happened. Revealing the Quran in parts allowed guidance to meet real situations directly, which made it clearer and more memorable."],
    de: ["Stellen, in denen der Koran Fragen beantwortet, die dem Propheten ﷺ gestellt wurden (die yasʾalūnaka-Stellen), veranschaulichen welche Weisheit der stufenweisen Offenbarung?", ["Fragen und Ereignisse zu beantworten, sobald sie auftraten", "Regeln zu verbergen, bis die Gemeinschaft größer war", "Die Offenbarungsfolge der Ordnung im muṣḥaf anzugleichen", "Die Schreibgeschwindigkeit der Schreiber zu prüfen"], "Viele Verse kamen als Antwort auf eine Frage oder ein Ereignis zu dessen Zeit. Die Offenbarung in Teilen ließ die Rechtleitung direkt auf reale Lagen treffen, was sie klarer und einprägsamer machte."],
    ar: ["الآيات التي تجيب عن أسئلة وُجّهت إلى النبي ﷺ تمثّل أيَّ حكمة من حِكَم التنجيم؟", ["مسايرة الحوادث والإجابة عن الأسئلة عند وقوعها", "إخفاء الأحكام حتى يكثر المسلمون", "موافقة ترتيب النزول لترتيب المصحف", "اختبار سرعة الكتبة"], "نزلت آيات كثيرة جوابًا عن سؤال أو حادثة وقت وقوعها، فكان التنجيم سبيلًا لملاقاة الهداية للوقائع مباشرة، وذلك أوضح لها وأثبت في الحفظ."] },

  // ---------- Laylat al-Qadr and the descent ----------
  { id: "ulr-029", s: "ulum", g: 1, d: 1, t: ["laylat-al-qadr", "descent"], src: "Ibn Kathīr, Tafsīr, on 2:185", v: "2:185",
    en: ["According to the verse shown, in which month was the Quran sent down?", ["Ramaḍān", "Shaʿbān", "Rajab", "Dhū al-Ḥijja"], "The verse states that Ramaḍān is the month in which the Quran was sent down as guidance for people. The night of its descent is Laylat al-Qadr, which falls in Ramaḍān."],
    de: ["In welchem Monat wurde der Koran laut dem gezeigten Vers herabgesandt?", ["Ramaḍān", "Shaʿbān", "Rajab", "Dhū al-Ḥijja"], "Der Vers sagt, dass Ramaḍān der Monat ist, in dem der Koran als Rechtleitung für die Menschen herabgesandt wurde. Die Nacht seines Herabkommens ist Laylat al-Qadr, die im Ramaḍān liegt."],
    ar: ["في أي شهر أُنزل القرآن بحسب الآية المعروضة؟", ["رمضان", "شعبان", "رجب", "ذو الحجة"], "نصّت الآية على أن رمضان هو الشهر الذي أُنزل فيه القرآن هدى للناس، وليلة نزوله ليلة القدر وهي في رمضان."] },
  { id: "ulr-030", s: "ulum", g: 1, d: 1, t: ["laylat-al-qadr"], src: "Ibn Kathīr, Tafsīr, on Sūrat al-Qadr", v: "97:3",
    en: ["According to the verse shown, Laylat al-Qadr is better than what?", ["A thousand months", "A hundred years", "A thousand nights", "Seventy years"], "The verse states that the Night of Decree is better than a thousand months: worship on it is better than worship in a thousand months that do not contain it."],
    de: ["Besser als was ist Laylat al-Qadr laut dem gezeigten Vers?", ["Tausend Monate", "Hundert Jahre", "Tausend Nächte", "Siebzig Jahre"], "Der Vers sagt, dass die Nacht der Bestimmung besser ist als tausend Monate: Gottesdienst in ihr ist besser als in tausend Monaten, in denen sie nicht vorkommt."],
    ar: ["ليلة القدر خير من ماذا بحسب الآية المعروضة؟", ["ألف شهر", "مئة سنة", "ألف ليلة", "سبعين سنة"], "نصّت الآية على أن ليلة القدر خير من ألف شهر، أي أن العمل فيها خير من العمل في ألف شهر ليس فيها ليلة القدر."] },
  { id: "ulr-031", s: "ulum", g: 3, d: 3, t: ["laylat-al-qadr", "descent"], src: "Ibn Kathīr, Tafsīr, on 44:3", v: "44:3", tr: ["jumhur"],
    en: ["Which night do the majority of exegetes take the 'blessed night' in the verse shown to be?", ["Laylat al-Qadr", "The night of mid-Shaʿbān", "The night of the Miʿrāj", "The first night of Ramaḍān"], "The majority identify it with Laylat al-Qadr, since 97:1 and 2:185 place the descent in Ramaḍān. A view attributed to ʿIkrima linked it to the night of mid-Shaʿbān; Ibn Kathīr calls that view far-fetched."],
    de: ["Welche Nacht ist nach der Mehrheit der Exegeten mit der „gesegneten Nacht“ im gezeigten Vers gemeint?", ["Laylat al-Qadr", "Die Nacht zur Mitte des Shaʿbān", "Die Nacht des Miʿrāj", "Die erste Nacht des Ramaḍān"], "Die Mehrheit setzt sie mit Laylat al-Qadr gleich, da 97:1 und 2:185 das Herabkommen in den Ramaḍān legen. Eine ʿIkrima zugeschriebene Ansicht bezog sie auf die Nacht zur Mitte des Shaʿbān; Ibn Kathīr nennt diese Ansicht weit hergeholt."],
    ar: ["ما الليلة المباركة في الآية المعروضة عند جمهور المفسرين؟", ["ليلة القدر", "ليلة النصف من شعبان", "ليلة المعراج", "أول ليلة من رمضان"], "الجمهور على أنها ليلة القدر، لأن سورة القدر وآية البقرة جعلتا الإنزال في رمضان، ونُسب إلى عكرمة أنها ليلة النصف من شعبان، وعدّه ابن كثير قولًا بعيدًا."] },
  { id: "ulr-032", s: "ulum", g: 2, d: 3, t: ["descent", "laylat-al-qadr"], src: "al-Suyūṭī, al-Itqān, ch. on how the revelation descended (reports of Ibn ʿAbbās)",
    en: ["The Quran was revealed on Laylat al-Qadr, yet also over about 23 years. How does the report of Ibn ʿAbbās reconcile these?", ["It descended all at once to the lowest heaven, then gradually to the Prophet ﷺ", "Only al-Fātiḥa descended on Laylat al-Qadr", "It descended on a different Laylat al-Qadr each year", "The Meccan part came at once and the Medinan part gradually"], "Ibn ʿAbbās said the Quran was sent down in one piece on Laylat al-Qadr to the lowest heaven, and from there it came down in portions over the years of the mission. Al-Suyūṭī calls this the soundest and best-known view."],
    de: ["Der Koran wurde in Laylat al-Qadr offenbart und doch über etwa 23 Jahre. Wie bringt der Bericht von Ibn ʿAbbās das in Einklang?", ["Er kam auf einmal zum untersten Himmel herab, dann stufenweise zum Propheten ﷺ", "Nur al-Fātiḥa kam in Laylat al-Qadr herab", "Er kam jedes Jahr in einer anderen Laylat al-Qadr herab", "Der mekkanische Teil kam auf einmal, der medinensische stufenweise"], "Ibn ʿAbbās sagte, der Koran sei in Laylat al-Qadr als Ganzes zum untersten Himmel herabgesandt worden und von dort über die Jahre der Sendung in Teilen herabgekommen. Al-Suyūṭī nennt dies die richtigste und bekannteste Ansicht."],
    ar: ["نزل القرآن في ليلة القدر، ونزل كذلك في نحو ثلاث وعشرين سنة. كيف يجمع أثر ابن عباس بين الأمرين؟", ["نزل جملة إلى السماء الدنيا ثم مفرقًا على النبي ﷺ", "لم ينزل ليلة القدر إلا الفاتحة", "كان ينزل في كل ليلة قدر من كل عام", "نزل المكي جملة والمدني مفرقًا"], "أخبر ابن عباس أن القرآن نزل جملة واحدة في ليلة القدر إلى السماء الدنيا، ثم نزل بعد ذلك مفرقًا في سنوات البعثة، وجعله السيوطي الأصح الأشهر."] },
  { id: "ulr-033", s: "ulum", g: 3, d: 4, t: ["descent"], src: "al-Suyūṭī, al-Itqān, ch. on how the revelation descended (reports of al-Ḥākim and al-Nasāʾī)",
    en: ["In the reports of Ibn ʿAbbās, what is the name of the place in the lowest heaven to which the Quran first descended as a whole?", ["Bayt al-ʿIzza", "Al-Bayt al-Maʿmūr", "Sidrat al-Muntahā", "Al-Lawḥ al-Maḥfūẓ"], "Ibn ʿAbbās named Bayt al-ʿIzza in the lowest heaven. Al-Bayt al-Maʿmūr is the house visited by angels, Sidrat al-Muntahā is in the highest heavens, and the Preserved Tablet is where the Quran is recorded before any descent."],
    de: ["Wie heißt in den Berichten von Ibn ʿAbbās der Ort im untersten Himmel, zu dem der Koran zuerst als Ganzes herabkam?", ["Bayt al-ʿIzza", "Al-Bayt al-Maʿmūr", "Sidrat al-Muntahā", "Al-Lawḥ al-Maḥfūẓ"], "Ibn ʿAbbās nannte Bayt al-ʿIzza im untersten Himmel. Al-Bayt al-Maʿmūr ist das von Engeln besuchte Haus, Sidrat al-Muntahā liegt in den höchsten Himmeln, und die Wohlverwahrte Tafel ist der Ort, an dem der Koran vor jedem Herabkommen verzeichnet ist."],
    ar: ["ما اسم الموضع في السماء الدنيا الذي نزل إليه القرآن جملة كما في آثار ابن عباس؟", ["بيت العزة", "البيت المعمور", "سدرة المنتهى", "اللوح المحفوظ"], "سمّاه ابن عباس بيت العزة في السماء الدنيا، أما البيت المعمور فبيت تزوره الملائكة، وسدرة المنتهى في أعلى السماوات، واللوح المحفوظ موضع كتابة القرآن قبل نزوله."] },
  { id: "ulr-034", s: "ulum", g: 4, d: 4, t: ["descent"], src: "al-Zarqānī, Manāhil al-ʿIrfān, ch. on the descents of the Quran", v: "85:22",
    en: ["Some scholars describe the Quran's descent in stages. For which stage is the verse shown usually cited?", ["Its being recorded in the Preserved Tablet", "Its descent to Bayt al-ʿIzza", "Its descent onto the Prophet's ﷺ heart", "Its being written by the scribes"], "Al-Zarqānī and others speak of the Quran's existence in the Preserved Tablet (citing 85:21–22), its descent to Bayt al-ʿIzza in the lowest heaven, and then its gradual descent upon the Prophet ﷺ through Jibrīl."],
    de: ["Manche Gelehrte beschreiben das Herabkommen des Korans in Stufen. Für welche Stufe wird der gezeigte Vers gewöhnlich angeführt?", ["Seine Verzeichnung auf der Wohlverwahrten Tafel", "Sein Herabkommen nach Bayt al-ʿIzza", "Sein Herabkommen auf das Herz des Propheten ﷺ", "Seine Niederschrift durch die Schreiber"], "Al-Zarqānī und andere sprechen vom Vorhandensein des Korans auf der Wohlverwahrten Tafel (mit Verweis auf 85:21–22), seinem Herabkommen nach Bayt al-ʿIzza im untersten Himmel und dann seinem stufenweisen Herabkommen auf den Propheten ﷺ durch Jibrīl."],
    ar: ["يذكر بعض العلماء للقرآن تنزلات. لأيّ تنزّل يُستشهد عادة بالآية المعروضة؟", ["ثبوته في اللوح المحفوظ", "نزوله إلى بيت العزة", "نزوله على قلب النبي ﷺ", "كتابة الكتبة له"], "ذكر الزرقاني وغيره ثبوت القرآن في اللوح المحفوظ مستدلين بآيتي البروج (85:21–22)، ثم نزوله إلى بيت العزة في السماء الدنيا، ثم نزوله منجمًا على النبي ﷺ بواسطة جبريل."] },
  // ---------- asbāb al-nuzūl ----------
  { id: "ulr-035", s: "ulum", g: 1, d: 2, t: ["asbab-al-nuzul"], src: "al-Wāḥidī, Asbāb al-Nuzūl, on Sūrat ʿAbasa; al-Tirmidhī, al-Jāmiʿ, Abwāb Tafsīr al-Qurʾān", v: "80:1",
    en: ["The surah that begins with the verse shown was revealed about a blind man who came to the Prophet ﷺ asking to be taught. Who was he?", ["ʿAbdullāh ibn Umm Maktūm", "Bilāl ibn Rabāḥ", "ʿAmmār ibn Yāsir", "Abū Dharr al-Ghifārī"], "Ibn Umm Maktūm, who was blind, came while the Prophet ﷺ was speaking with leaders of Quraysh, hoping they would accept Islam. The surah taught that the sincere seeker deserves attention first."],
    de: ["Die Sure, die mit dem gezeigten Vers beginnt, wurde über einen blinden Mann offenbart, der zum Propheten ﷺ kam und um Unterweisung bat. Wer war er?", ["ʿAbdullāh ibn Umm Maktūm", "Bilāl ibn Rabāḥ", "ʿAmmār ibn Yāsir", "Abū Dharr al-Ghifārī"], "Der blinde Ibn Umm Maktūm kam, während der Prophet ﷺ mit Anführern der Quraysh sprach, in der Hoffnung, sie würden den Islam annehmen. Die Sure lehrte, dass der aufrichtig Suchende zuerst Beachtung verdient."],
    ar: ["نزلت السورة التي أولها الآية المعروضة في رجل أعمى جاء النبي ﷺ يطلب التعليم. مَن هو؟", ["عبد الله ابن أم مكتوم", "بلال بن رباح", "عمار بن ياسر", "أبو ذر الغفاري"], "جاء ابن أم مكتوم الأعمى والنبي ﷺ يحدّث بعض كبراء قريش رجاء إسلامهم، فنزلت السورة تعلّم أن طالب الهداية الصادق أولى بالإقبال."] },
  { id: "ulr-036", s: "ulum", g: 1, d: 2, t: ["asbab-al-nuzul"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Tafsīr, Sūrat al-Masad", v: "111:1",
    en: ["The surah of the verse shown was revealed after the Prophet ﷺ called Quraysh together from al-Ṣafā. Who had answered him with a curse?", ["Abū Lahab", "Abū Jahl", "Al-Walīd ibn al-Mughīra", "Umayya ibn Khalaf"], "Ibn ʿAbbās reports in al-Bukhārī that when the Prophet ﷺ warned Quraysh from al-Ṣafā, his uncle Abū Lahab cursed him, and this surah was revealed about him."],
    de: ["Die Sure des gezeigten Verses wurde offenbart, nachdem der Prophet ﷺ die Quraysh von al-Ṣafā aus zusammengerufen hatte. Wer hatte ihm mit einem Fluch geantwortet?", ["Abū Lahab", "Abū Jahl", "Al-Walīd ibn al-Mughīra", "Umayya ibn Khalaf"], "Ibn ʿAbbās berichtet bei al-Bukhārī, dass sein Onkel Abū Lahab ihn verfluchte, als der Prophet ﷺ die Quraysh von al-Ṣafā aus warnte, und daraufhin wurde diese Sure über ihn offenbart."],
    ar: ["نزلت سورة الآية المعروضة بعد أن جمع النبي ﷺ قريشًا من على الصفا. مَن الذي ردّ عليه بالدعاء عليه؟", ["أبو لهب", "أبو جهل", "الوليد بن المغيرة", "أمية بن خلف"], "روى البخاري عن ابن عباس أن النبي ﷺ لما أنذر قريشًا من على الصفا دعا عليه عمه أبو لهب، فنزلت فيه هذه السورة."] },
  { id: "ulr-037", s: "ulum", g: 1, d: 2, t: ["asbab-al-nuzul"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Maghāzī, ḥadīth al-ifk", v: "24:11",
    en: ["The verse shown begins the passage revealed about the slander (al-ifk). Whose innocence did it declare?", ["ʿĀʾisha", "Ḥafṣa", "Zaynab bint Jaḥsh", "Umm Salama"], "The verses of al-Nūr from this verse onward were revealed to clear ʿĀʾisha of the false accusation spread by the hypocrites after the expedition of Banū al-Muṣṭaliq."],
    de: ["Der gezeigte Vers leitet die Stelle ein, die über die Verleumdung (al-ifk) offenbart wurde. Wessen Unschuld erklärte sie?", ["ʿĀʾisha", "Ḥafṣa", "Zaynab bint Jaḥsh", "Umm Salama"], "Die Verse von al-Nūr ab diesem Vers wurden offenbart, um ʿĀʾisha von der falschen Anschuldigung freizusprechen, die die Heuchler nach dem Feldzug gegen die Banū al-Muṣṭaliq verbreitet hatten."],
    ar: ["الآية المعروضة أول الآيات النازلة في حادثة الإفك. براءة مَن أعلنت؟", ["عائشة", "حفصة", "زينب بنت جحش", "أم سلمة"], "نزلت آيات سورة النور من هذه الآية في براءة عائشة رضي الله عنها مما أشاعه المنافقون بعد غزوة بني المصطلق."] },
  { id: "ulr-038", s: "ulum", g: 2, d: 2, t: ["asbab-al-nuzul", "definitions"], src: "al-Suyūṭī, al-Itqān, ch. on asbāb al-nuzūl",
    en: ["What is sabab al-nuzūl (occasion of revelation)?", ["An event or question about which revelation came at the time it occurred", "The reason a surah is placed where it is in the muṣḥaf", "The place in which a verse was revealed", "The reason one reading differs from another"], "An occasion of revelation is an incident or a question in the Prophet's ﷺ time in response to which a verse or passage came down, close to when it occurred."],
    de: ["Was ist sabab al-nuzūl (Offenbarungsanlass)?", ["Ein Ereignis oder eine Frage, zu der die Offenbarung zu ihrer Zeit herabkam", "Der Grund, warum eine Sure an ihrer Stelle im muṣḥaf steht", "Der Ort, an dem ein Vers offenbart wurde", "Der Grund, warum eine Lesart von einer anderen abweicht"], "Ein Offenbarungsanlass ist ein Vorfall oder eine Frage zur Zeit des Propheten ﷺ, auf die hin ein Vers oder eine Stelle herabkam, zeitnah zu ihrem Eintreten."],
    ar: ["ما سبب النزول؟", ["ما نزلت الآية بشأنه من حادثة أو سؤال وقت وقوعه", "علة وضع السورة في موضعها من المصحف", "المكان الذي نزلت فيه الآية", "سبب اختلاف قراءة عن أخرى"], "سبب النزول ما نزلت الآية أو الآيات متحدثة عنه أو مبيّنة لحكمه أيام وقوعه، من حادثة أو سؤال في زمن النبي ﷺ."] },
  { id: "ulr-039", s: "ulum", g: 2, d: 3, t: ["asbab-al-nuzul", "general-wording"], src: "al-Suyūṭī, al-Itqān, ch. on asbāb al-nuzūl; al-Zarkashī, al-Burhān, first category", tr: ["jumhur"],
    en: ["What does the principle 'al-ʿibra bi-ʿumūm al-lafẓ lā bi-khuṣūṣ al-sabab' mean?", ["The ruling follows the general wording of the verse, not only the specific person or event", "A verse applies only to the person it was revealed about", "The occasion of revelation overrides the wording of the verse", "General verses are always restricted by their occasion"], "The majority hold that when a verse is general in wording, its ruling covers everyone it includes, even though it was revealed on a particular occasion. The occasion is the clearest case of the verse, not its limit."],
    de: ["Was bedeutet der Grundsatz „al-ʿibra bi-ʿumūm al-lafẓ lā bi-khuṣūṣ al-sabab“?", ["Die Regel folgt dem allgemeinen Wortlaut des Verses, nicht nur der konkreten Person oder dem Ereignis", "Ein Vers gilt nur für die Person, über die er offenbart wurde", "Der Offenbarungsanlass hat Vorrang vor dem Wortlaut des Verses", "Allgemeine Verse werden stets durch ihren Anlass eingeschränkt"], "Die Mehrheit vertritt, dass ein im Wortlaut allgemeiner Vers alle umfasst, die er einschließt, auch wenn er zu einem bestimmten Anlass offenbart wurde. Der Anlass ist der deutlichste Anwendungsfall des Verses, nicht seine Grenze."],
    ar: ["ما معنى قاعدة «العبرة بعموم اللفظ لا بخصوص السبب»؟", ["الحكم يتعلق بعموم لفظ الآية لا بالشخص أو الحادثة وحدها", "الآية لا تتناول إلا من نزلت فيه", "سبب النزول مقدّم على لفظ الآية", "الآيات العامة مقصورة دائمًا على أسبابها"], "مذهب الجمهور أن اللفظ إذا كان عامًّا شمل حكمه كل ما يتناوله وإن نزل على سبب خاص، فصورة السبب أوضح أفراده لا حدّ له."] },
  { id: "ulr-040", s: "ulum", g: 2, d: 3, t: ["asbab-al-nuzul"], src: "Ibn Kathīr, Tafsīr, on 58:1", v: "58:1",
    en: ["The verse shown was revealed about a woman who pleaded with the Prophet ﷺ about her husband's ẓihār. Who was she, as she is commonly named?", ["Khawla bint Thaʿlaba", "Fāṭima bint Qays", "Asmāʾ bint Abī Bakr", "Umm Kulthūm bint ʿUqba"], "She is commonly named Khawla bint Thaʿlaba, wife of Aws ibn al-Ṣāmit, who had declared ẓihār against her. ʿĀʾisha said she was in the room and did not hear all that was said, yet Allah heard it."],
    de: ["Der gezeigte Vers wurde über eine Frau offenbart, die beim Propheten ﷺ wegen des ẓihār ihres Mannes vorsprach. Wer war sie nach der üblichen Benennung?", ["Khawla bint Thaʿlaba", "Fāṭima bint Qays", "Asmāʾ bint Abī Bakr", "Umm Kulthūm bint ʿUqba"], "Sie wird üblicherweise Khawla bint Thaʿlaba genannt, Ehefrau von Aws ibn al-Ṣāmit, der gegen sie ẓihār ausgesprochen hatte. ʿĀʾisha sagte, sie sei im Raum gewesen und habe nicht alles gehört, Allah aber habe es gehört."],
    ar: ["نزلت الآية المعروضة في امرأة جادلت النبي ﷺ في ظهار زوجها. مَن هي على المشهور؟", ["خولة بنت ثعلبة", "فاطمة بنت قيس", "أسماء بنت أبي بكر", "أم كلثوم بنت عقبة"], "المشهور أنها خولة بنت ثعلبة زوج أوس بن الصامت الذي ظاهر منها، وذكرت عائشة أنها كانت في ناحية البيت لا تسمع بعض كلامها، والله سمعه."] },
  { id: "ulr-041", s: "ulum", g: 2, d: 3, t: ["asbab-al-nuzul"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Tafsīr, Sūrat al-Ḍuḥā", v: "93:3",
    en: ["What occasioned the surah of the verse shown, according to the report of Jundub in al-Bukhārī?", ["A pause in revelation and a taunt that his Lord had left him", "The death of his son Ibrāhīm", "The boycott of Banū Hāshim in the valley", "The rejection he met in al-Ṭāʾif"], "Jundub reports that the Prophet ﷺ was unwell and did not rise for a night or two, revelation paused, and a woman taunted him that he had been abandoned. Al-Ḍuḥā was revealed to deny this."],
    de: ["Was war nach dem Bericht von Jundub bei al-Bukhārī der Anlass der Sure des gezeigten Verses?", ["Eine Pause der Offenbarung und der Spott, sein Herr habe ihn verlassen", "Der Tod seines Sohnes Ibrāhīm", "Der Boykott der Banū Hāshim im Tal", "Die Ablehnung, die er in al-Ṭāʾif erfuhr"], "Jundub berichtet, dass der Prophet ﷺ unwohl war und ein oder zwei Nächte nicht aufstand, die Offenbarung pausierte und eine Frau spottete, er sei verlassen worden. Al-Ḍuḥā wurde offenbart, um dies zurückzuweisen."],
    ar: ["ما سبب نزول سورة الآية المعروضة كما في رواية جندب عند البخاري؟", ["فتور الوحي وقول قائلة إن ربه تركه", "وفاة ابنه إبراهيم", "حصار بني هاشم في الشعب", "ما لقيه من أهل الطائف"], "روى جندب أن النبي ﷺ اشتكى فلم يقم ليلة أو ليلتين وأبطأ الوحي، فعيّرته امرأة بأنه قد تُرك، فنزلت سورة الضحى نفيًا لذلك."] },

  // ---------- Meccan and Medinan (stage 1–2) ----------
  { id: "ulr-042", s: "ulum", g: 1, d: 1, t: ["meccan-medinan"], src: "al-Suyūṭī, al-Itqān, ch. on Meccan and Medinan",
    en: ["Which of these surahs is Meccan?", ["Al-Muddaththir", "Al-Baqara", "Al-Nisāʾ", "Al-Anfāl"], "Al-Muddaththir is among the earliest Meccan revelations. Al-Baqara, al-Nisāʾ and al-Anfāl are Medinan, dealing with laws, family and the battle of Badr."],
    de: ["Welche dieser Suren ist mekkanisch?", ["Al-Muddaththir", "Al-Baqara", "Al-Nisāʾ", "Al-Anfāl"], "Al-Muddaththir gehört zu den frühesten mekkanischen Offenbarungen. Al-Baqara, al-Nisāʾ und al-Anfāl sind medinensisch und behandeln Gesetze, Familie und die Schlacht von Badr."],
    ar: ["أي هذه السور مكية؟", ["المدثر", "البقرة", "النساء", "الأنفال"], "سورة المدثر من أوائل ما نزل بمكة، أما البقرة والنساء والأنفال فمدنيات تتناول الأحكام والأسرة وغزوة بدر."] },
  { id: "ulr-043", s: "ulum", g: 1, d: 2, t: ["meccan-medinan"], src: "al-Suyūṭī, al-Itqān, ch. on Meccan and Medinan",
    en: ["Which of these surahs is Medinan?", ["Al-Nūr", "Yā-Sīn", "Al-Mulk", "Maryam"], "Al-Nūr is Medinan: it contains the slander passage, the punishment for zinā and rules of modesty. Yā-Sīn, al-Mulk and Maryam are Meccan."],
    de: ["Welche dieser Suren ist medinensisch?", ["Al-Nūr", "Yā-Sīn", "Al-Mulk", "Maryam"], "Al-Nūr ist medinensisch: Sie enthält die Stelle über die Verleumdung, die Strafe für zinā und Regeln der Schamhaftigkeit. Yā-Sīn, al-Mulk und Maryam sind mekkanisch."],
    ar: ["أي هذه السور مدنية؟", ["النور", "يس", "الملك", "مريم"], "سورة النور مدنية، ففيها حادثة الإفك وحد الزنا وأحكام الاستئذان والحجاب، أما يس والملك ومريم فمكيات."] },
  { id: "ulr-044", s: "ulum", g: 2, d: 2, t: ["meccan-medinan", "definitions"], src: "al-Suyūṭī, al-Itqān, ch. on Meccan and Medinan",
    en: ["By the best-known definition, what makes a verse Medinan?", ["It was revealed after the hijra, wherever it came down", "It was revealed inside the city of Medina", "It addresses the believers directly", "It contains a legal ruling"], "Al-Suyūṭī calls the time-based definition the best known: Meccan is what came before the hijra and Medinan what came after it, even if revealed in Mecca or on a journey."],
    de: ["Was macht nach der bekanntesten Definition einen Vers medinensisch?", ["Er wurde nach der Hidschra offenbart, gleich wo er herabkam", "Er wurde innerhalb der Stadt Medina offenbart", "Er spricht die Gläubigen direkt an", "Er enthält eine Rechtsbestimmung"], "Al-Suyūṭī nennt die zeitbezogene Definition die bekannteste: Mekkanisch ist, was vor der Hidschra kam, medinensisch, was danach kam, auch wenn es in Mekka oder auf einer Reise offenbart wurde."],
    ar: ["ما الذي يجعل الآية مدنية على التعريف الأشهر؟", ["نزولها بعد الهجرة أينما نزلت", "نزولها داخل المدينة", "خطابها للمؤمنين مباشرة", "اشتمالها على حكم فقهي"], "الأشهر عند السيوطي اعتبار الزمان: المكي ما نزل قبل الهجرة، والمدني ما نزل بعدها وإن نزل بمكة أو في سفر."] },
  { id: "ulr-045", s: "ulum", g: 2, d: 2, t: ["meccan-medinan"], src: "Mannāʿ al-Qaṭṭān, Mabāḥith fī ʿUlūm al-Qurʾān, ch. on Meccan and Medinan",
    en: ["Which set of features is typical of Meccan revelation?", ["Tawḥīd, resurrection and stories of earlier prophets, often in short verses", "Detailed laws of inheritance, divorce and trade", "Rulings on fighting, treaties and spoils of war", "Exposure of the hypocrites and their schemes"], "Meccan revelation focuses on belief: the oneness of Allah, the resurrection and the stories of earlier nations, usually in short, forceful verses. Laws, treaties and the hypocrites are Medinan themes."],
    de: ["Welche Merkmale sind typisch für mekkanische Offenbarung?", ["Tawḥīd, Auferstehung und Geschichten früherer Propheten, oft in kurzen Versen", "Ausführliche Regeln zu Erbe, Scheidung und Handel", "Bestimmungen zu Kampf, Verträgen und Kriegsbeute", "Die Entlarvung der Heuchler und ihrer Pläne"], "Mekkanische Offenbarung stellt den Glauben in den Mittelpunkt: die Einheit Allahs, die Auferstehung und die Geschichten früherer Völker, meist in kurzen, eindringlichen Versen. Gesetze, Verträge und Heuchler sind medinensische Themen."],
    ar: ["أي هذه السمات من خصائص القرآن المكي غالبًا؟", ["التوحيد والبعث وقصص الأنبياء مع قِصَر الآيات", "تفصيل أحكام المواريث والطلاق والبيوع", "أحكام القتال والمعاهدات والغنائم", "كشف المنافقين ومكايدهم"], "يغلب على المكي تقرير العقيدة: التوحيد والبعث وقصص الأمم السابقة، في آيات قصيرة قوية الوقع، أما الأحكام والمعاهدات والمنافقون فمن موضوعات المدني."] },

  // ---------- names and descriptions of the Quran (stage 1–2) ----------
  { id: "ulr-046", s: "ulum", g: 1, d: 1, t: ["quran-names"], src: "Ibn Kathīr, Tafsīr, on 25:1", v: "25:1", w: 4,
    en: ["The highlighted word is one of the names of the Quran. What does it mean?", ["The criterion between truth and falsehood", "The recitation", "The reminder", "The light"], "Al-Furqān means that which distinguishes (faraqa) between truth and falsehood, guidance and misguidance; the surah carrying this name opens with it."],
    de: ["Das markierte Wort ist einer der Namen des Korans. Was bedeutet es?", ["Das Unterscheidungsmerkmal zwischen Wahrheit und Falschheit", "Die Rezitation", "Die Ermahnung", "Das Licht"], "Al-Furqān bedeutet das, was zwischen Wahrheit und Falschheit, Rechtleitung und Irreleitung unterscheidet (faraqa); die gleichnamige Sure beginnt damit."],
    ar: ["الكلمة المظللة من أسماء القرآن. ما معناها؟", ["الفارق بين الحق والباطل", "المقروء", "التذكرة", "النور"], "الفرقان ما يفرق بين الحق والباطل والهدى والضلال، وبه افتُتحت السورة المسماة به."] },
  { id: "ulr-047", s: "ulum", g: 2, d: 3, t: ["quran-names"], src: "Ibn Kathīr, Tafsīr, on 4:174", v: "4:174", w: 10,
    en: ["In the verse shown, the Quran is described by the highlighted word. Which description is it?", ["A light", "A cure", "A spirit", "A criterion"], "The verse describes the Quran as a clear light sent down to people, because it illuminates the way of guidance. Cure, spirit and criterion are other descriptions found elsewhere."],
    de: ["Im gezeigten Vers wird der Koran mit dem markierten Wort beschrieben. Welche Beschreibung ist es?", ["Ein Licht", "Eine Heilung", "Ein Geist", "Ein Unterscheidungsmerkmal"], "Der Vers beschreibt den Koran als ein deutliches Licht, das zu den Menschen herabgesandt wurde, weil er den Weg der Rechtleitung erhellt. Heilung, Geist und Unterscheidungsmerkmal sind andere Beschreibungen an anderen Stellen."],
    ar: ["وُصف القرآن في الآية المعروضة بالكلمة المظللة. ما هذا الوصف؟", ["النور", "الشفاء", "الروح", "الفرقان"], "وصفت الآية القرآن بأنه نور مبين أنزله الله إلى الناس لأنه يضيء طريق الهداية، أما الشفاء والروح والفرقان فأوصاف وردت في مواضع أخرى."] },

  // ---------- counts (stage 1–2) ----------
  { id: "ulr-048", s: "ulum", g: 1, d: 1, t: ["surah-count"], src: "al-Suyūṭī, al-Itqān, ch. on the number of surahs and verses",
    en: ["How many surahs does the Quran contain?", ["114", "110", "120", "99"], "The muṣḥaf contains 114 surahs, from al-Fātiḥa to al-Nās, by the agreement of the Muslims on the ʿUthmānic muṣḥaf."],
    de: ["Wie viele Suren enthält der Koran?", ["114", "110", "120", "99"], "Der muṣḥaf enthält 114 Suren, von al-Fātiḥa bis al-Nās, nach der Übereinstimmung der Muslime über den ʿuthmānischen muṣḥaf."],
    ar: ["كم عدد سور القرآن؟", ["مئة وأربع عشرة", "مئة وعشر", "مئة وعشرون", "تسع وتسعون"], "سور القرآن مئة وأربع عشرة سورة من الفاتحة إلى الناس، وعليه إجماع المسلمين في المصحف العثماني."] },
  { id: "ulr-049", s: "ulum", g: 1, d: 1, t: ["surah-count"], src: "al-Suyūṭī, al-Itqān, ch. on the number of surahs and verses",
    en: ["Which is the longest surah of the Quran?", ["Al-Baqara", "Āl ʿImrān", "Al-Nisāʾ", "Al-Aʿrāf"], "Al-Baqara is the longest surah, with 286 verses in the Kufan count. Āl ʿImrān has 200 and al-Aʿrāf 206."],
    de: ["Welche ist die längste Sure des Korans?", ["Al-Baqara", "Āl ʿImrān", "Al-Nisāʾ", "Al-Aʿrāf"], "Al-Baqara ist die längste Sure mit 286 Versen nach kufischer Zählung. Āl ʿImrān hat 200 und al-Aʿrāf 206."],
    ar: ["ما أطول سور القرآن؟", ["البقرة", "آل عمران", "النساء", "الأعراف"], "البقرة أطول السور، وآياتها مئتان وست وثمانون في العدّ الكوفي، وآل عمران مئتا آية، والأعراف مئتان وست."] },
  { id: "ulr-050", s: "ulum", g: 1, d: 2, t: ["verse-count"], src: "al-Dānī, al-Bayān fī ʿAdd Āy al-Qurʾān",
    en: ["Which of these surahs has only three verses?", ["Al-Kawthar", "Al-Ikhlāṣ", "Al-Falaq", "Al-Nās"], "Al-Kawthar has three verses, as do al-ʿAṣr and al-Naṣr. Al-Ikhlāṣ has four, al-Falaq five and al-Nās six."],
    de: ["Welche dieser Suren hat nur drei Verse?", ["Al-Kawthar", "Al-Ikhlāṣ", "Al-Falaq", "Al-Nās"], "Al-Kawthar hat drei Verse, ebenso al-ʿAṣr und al-Naṣr. Al-Ikhlāṣ hat vier, al-Falaq fünf und al-Nās sechs."],
    ar: ["أي هذه السور آياتها ثلاث فقط؟", ["الكوثر", "الإخلاص", "الفلق", "الناس"], "سورة الكوثر ثلاث آيات، ومثلها العصر والنصر، أما الإخلاص فأربع، والفلق خمس، والناس ست."] },
  { id: "ulr-051", s: "ulum", g: 1, d: 1, t: ["surah-count", "basmala"], src: "al-Suyūṭī, al-Itqān, ch. on the order of surahs",
    en: ["Which surah does not begin with the basmala?", ["Al-Tawba", "Al-Anfāl", "Al-Fātiḥa", "Al-Naml"], "Al-Tawba (Barāʾa) is the only surah without the basmala at its start. Al-Naml is special in the opposite way: it has the basmala at its start and again within the surah."],
    de: ["Welche Sure beginnt nicht mit der basmala?", ["Al-Tawba", "Al-Anfāl", "Al-Fātiḥa", "Al-Naml"], "Al-Tawba (Barāʾa) ist die einzige Sure ohne basmala am Anfang. Al-Naml ist umgekehrt besonders: Sie hat die basmala am Anfang und noch einmal innerhalb der Sure."],
    ar: ["أي سورة لا تُفتتح بالبسملة؟", ["التوبة", "الأنفال", "الفاتحة", "النمل"], "سورة التوبة (براءة) هي السورة الوحيدة التي لم تُكتب البسملة في أولها، وعلى العكس منها النمل ففيها البسملة في أولها وفي أثنائها."] },
  { id: "ulr-052", s: "ulum", g: 2, d: 2, t: ["verse-count", "basmala"], src: "Ibn Kathīr, Tafsīr, on 27:30", v: "27:30", w: 5,
    en: ["Why is the highlighted word in the verse shown notable for counts of the Quran?", ["It begins a basmala inside a surah, so al-Naml contains it twice", "It is the middle word of the whole Quran", "It begins the longest verse of the Quran", "It is the only word written without an alif"], "In the letter of Sulaymān to the Queen of Sabaʾ, the basmala occurs within the text. So al-Naml has the basmala twice, balancing al-Tawba, which has none, and the basmala occurs 114 times in the muṣḥaf."],
    de: ["Warum ist das markierte Wort im gezeigten Vers für die Zählungen des Korans bemerkenswert?", ["Es beginnt eine basmala innerhalb einer Sure, sodass al-Naml sie zweimal enthält", "Es ist das mittlere Wort des ganzen Korans", "Es beginnt den längsten Vers des Korans", "Es ist das einzige ohne alif geschriebene Wort"], "Im Brief Sulaymāns an die Königin von Sabaʾ steht die basmala im Text. Daher hat al-Naml die basmala zweimal, als Ausgleich zu al-Tawba, die keine hat, und die basmala kommt im muṣḥaf 114-mal vor."],
    ar: ["لماذا تُذكر الكلمة المظللة في الآية المعروضة في مباحث العدّ؟", ["لأنها أول بسملة في أثناء سورة فتكون في النمل مرتين", "لأنها الكلمة الوسطى من القرآن كله", "لأنها أول أطول آية في القرآن", "لأنها الكلمة الوحيدة المكتوبة بلا ألف"], "جاءت البسملة في كتاب سليمان إلى ملكة سبأ في أثناء السورة، فصارت في النمل مرتين، ويقابلها خلوّ التوبة منها، فتكون البسملة في المصحف مئة وأربع عشرة مرة."] },
  { id: "ulr-053", s: "ulum", g: 2, d: 2, t: ["verse-count"], src: "al-Dānī, al-Bayān fī ʿAdd Āy al-Qurʾān, on the Kufan count",
    en: ["How many verses does the Quran have in the Kufan count, which is used in muṣḥafs printed in the riwāya of Ḥafṣ?", ["6236", "6666", "6214", "6000"], "The Kufan count, transmitted from Abū ʿAbd al-Raḥmān al-Sulamī from ʿAlī, gives 6236 verses. The popular figure 6666 has no basis in the counting schools."],
    de: ["Wie viele Verse hat der Koran nach der kufischen Zählung, die in den nach der riwāya Ḥafṣ gedruckten Exemplaren verwendet wird?", ["6236", "6666", "6214", "6000"], "Die kufische Zählung, überliefert von Abū ʿAbd al-Raḥmān al-Sulamī von ʿAlī, ergibt 6236 Verse. Die verbreitete Zahl 6666 hat in den Zählschulen keine Grundlage."],
    ar: ["كم عدد آيات القرآن في العدّ الكوفي المعتمد في المصاحف المطبوعة برواية حفص؟", ["6236", "6666", "6214", "6000"], "العدّ الكوفي المروي عن أبي عبد الرحمن السلمي عن علي رضي الله عنه ستة آلاف ومئتان وست وثلاثون آية، أما الرقم 6666 المشهور على الألسنة فلا أصل له في مذاهب العدّ."] },

  // ---------- scribes (stage 1) ----------
  { id: "ulr-054", s: "ulum", g: 1, d: 2, t: ["scribes"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb Faḍāʾil al-Qurʾān, chapter on the scribe of the Prophet ﷺ",
    en: ["Which Companion is best known as the scribe of the revelation in Medina?", ["Zayd ibn Thābit", "Abū Hurayra", "Anas ibn Mālik", "Salmān al-Fārisī"], "Zayd ibn Thābit wrote down the revelation for the Prophet ﷺ in Medina; al-Bukhārī reports the Prophet ﷺ calling for him when a verse came down. Anas served the Prophet ﷺ but was not his scribe."],
    de: ["Welcher Gefährte ist als Schreiber der Offenbarung in Medina am bekanntesten?", ["Zayd ibn Thābit", "Abū Hurayra", "Anas ibn Mālik", "Salmān al-Fārisī"], "Zayd ibn Thābit schrieb die Offenbarung für den Propheten ﷺ in Medina auf; al-Bukhārī berichtet, wie der Prophet ﷺ nach ihm rufen ließ, wenn ein Vers herabkam. Anas diente dem Propheten ﷺ, war aber nicht sein Schreiber."],
    ar: ["مَن أشهر كتّاب الوحي بالمدينة من الصحابة؟", ["زيد بن ثابت", "أبو هريرة", "أنس بن مالك", "سلمان الفارسي"], "كان زيد بن ثابت يكتب الوحي للنبي ﷺ بالمدينة، وروى البخاري أن النبي ﷺ كان يدعوه إذا نزلت الآية، أما أنس فكان خادمه لا كاتبه."] },
  // ---------- stage 3 ----------
  { id: "ulr-055", s: "ulum", g: 3, d: 3, t: ["asbab-al-nuzul"], src: "al-Wāḥidī, Asbāb al-Nuzūl, introduction",
    en: ["According to al-Wāḥidī, how alone may the occasion of a verse's revelation be known?", ["By transmission from those who witnessed the revelation", "By reasoning from the meaning of the verse", "By the position of the verse in the muṣḥaf", "By comparing the verse with similar verses"], "Al-Wāḥidī states in the introduction of his Asbāb al-Nuzūl that speaking about occasions of revelation is only permissible through narration and hearing from those who witnessed it. Personal reasoning cannot establish a historical event."],
    de: ["Wodurch allein kann nach al-Wāḥidī der Offenbarungsanlass eines Verses bekannt werden?", ["Durch Überlieferung von denen, die die Offenbarung miterlebten", "Durch Schlussfolgerung aus der Bedeutung des Verses", "Durch die Stellung des Verses im muṣḥaf", "Durch den Vergleich mit ähnlichen Versen"], "Al-Wāḥidī sagt in der Einleitung seines Asbāb al-Nuzūl, dass man über Offenbarungsanlässe nur auf Grundlage von Überlieferung und Hören von den Augenzeugen sprechen darf. Eigenes Urteil kann ein geschichtliches Ereignis nicht feststellen."],
    ar: ["بماذا وحده يُعرف سبب نزول الآية عند الواحدي؟", ["بالرواية والسماع ممن شاهدوا التنزيل", "بالاستنباط من معنى الآية", "بموضع الآية في المصحف", "بمقارنة الآية بنظائرها"], "قرّر الواحدي في مقدمة أسباب النزول أنه لا يحل القول في أسباب النزول إلا بالرواية والسماع ممن شاهدوا التنزيل، فالواقعة التاريخية لا تثبت بالرأي."] },
  { id: "ulr-056", s: "ulum", g: 3, d: 4, t: ["asbab-al-nuzul", "general-wording"], src: "al-Suyūṭī, al-Itqān, ch. on asbāb al-nuzūl; Ibn Kathīr, Tafsīr, on 58:1–4", v: "58:1", tr: ["jumhur"],
    en: ["The ẓihār verses came down about Khawla bint Thaʿlaba and her husband. On what basis do jurists apply their ruling to every man who pronounces ẓihār?", ["The general wording of the verses, which is not restricted to the occasion", "Analogy with the case of Khawla, since the verses concern her alone", "A later verse that extended the ruling to all", "The consensus that every occasion is a mere example"], "The following verses speak generally of 'those who pronounce ẓihār', so the ruling covers all by its wording; this is the standard illustration of the principle that the lesson lies in the generality of the wording, not the specific cause."],
    de: ["Die ẓihār-Verse kamen über Khawla bint Thaʿlaba und ihren Mann herab. Auf welcher Grundlage wenden die Juristen ihre Regel auf jeden Mann an, der ẓihār ausspricht?", ["Der allgemeine Wortlaut der Verse, der nicht auf den Anlass beschränkt ist", "Analogie zum Fall Khawla, da die Verse nur sie betreffen", "Ein späterer Vers, der die Regel auf alle ausdehnte", "Der Konsens, dass jeder Anlass bloß ein Beispiel ist"], "Die folgenden Verse sprechen allgemein von „denjenigen, die ẓihār aussprechen“; daher umfasst die Regel alle durch ihren Wortlaut. Das ist das übliche Beispiel für den Grundsatz, dass die Lehre in der Allgemeinheit des Wortlauts liegt, nicht im besonderen Anlass."],
    ar: ["نزلت آيات الظهار في خولة بنت ثعلبة وزوجها. على أي أساس يُجري الفقهاء حكمها على كل مظاهر؟", ["عموم لفظ الآيات غير المقصور على السبب", "القياس على خولة لأن الآيات خاصة بها", "آية لاحقة عمّمت الحكم", "الإجماع على أن كل سبب مجرد مثال"], "جاءت الآيات التالية بلفظ عام في الذين يظاهرون من نسائهم، فشمل الحكم كل مظاهر بلفظه، وهذا المثال المشهور لقاعدة العبرة بعموم اللفظ لا بخصوص السبب."] },
  { id: "ulr-057", s: "ulum", g: 3, d: 4, t: ["asbab-al-nuzul"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Ḥajj, chapter on the obligation of saʿy", v: "2:158",
    en: ["ʿUrwa understood the phrase 'there is no blame' in the verse shown to mean that saʿy between al-Ṣafā and al-Marwa is optional. How did ʿĀʾisha correct him?", ["By explaining the occasion: some Anṣār had felt it sinful to go between them", "By citing a later verse that made saʿy obligatory", "By noting that the phrase is a later addition to the verse", "By pointing to a different reading of the verse"], "ʿĀʾisha explained that some of the Anṣār had felt uneasy about going between the two hills because of pre-Islamic practice, so the verse removed that sense of sin. This is a classic example of how knowing the occasion prevents misunderstanding."],
    de: ["ʿUrwa verstand die Wendung „es ist keine Sünde“ im gezeigten Vers so, dass der saʿy zwischen al-Ṣafā und al-Marwa freiwillig sei. Wie korrigierte ihn ʿĀʾisha?", ["Durch Erklärung des Anlasses: Einige der Anṣār hatten das Gehen zwischen ihnen für sündhaft gehalten", "Durch einen späteren Vers, der den saʿy verpflichtend machte", "Durch den Hinweis, die Wendung sei ein späterer Zusatz", "Durch Verweis auf eine andere Lesart des Verses"], "ʿĀʾisha erklärte, dass einige der Anṣār wegen vorislamischer Bräuche Bedenken hatten, zwischen den beiden Hügeln zu gehen; der Vers nahm dieses Gefühl der Sünde weg. Das ist ein klassisches Beispiel dafür, wie die Kenntnis des Anlasses Missverständnisse verhindert."],
    ar: ["فهم عروة من نفي الجناح في الآية المعروضة أن السعي بين الصفا والمروة غير واجب. كيف صحّحت له عائشة فهمه؟", ["ببيان السبب: أن بعض الأنصار تحرّجوا من الطواف بينهما", "بذكر آية لاحقة أوجبت السعي", "بأن نفي الجناح زيادة لاحقة في الآية", "بالإشارة إلى قراءة أخرى للآية"], "بيّنت عائشة أن بعض الأنصار كانوا يتحرّجون من الطواف بين الصفا والمروة لأمر كان في الجاهلية، فنزلت الآية برفع الحرج، وهذا مثال مشهور على أن معرفة السبب تدفع الفهم الخاطئ."] },
  { id: "ulr-058", s: "ulum", g: 3, d: 3, t: ["asbab-al-nuzul"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Tafsīr, Sūrat al-Tawba", v: "9:84",
    en: ["The verse shown, forbidding the funeral prayer over hypocrites, was revealed after the Prophet ﷺ prayed over whom?", ["ʿAbdullāh ibn Ubayy ibn Salūl", "Abū Ṭālib", "Al-Walīd ibn al-Mughīra", "Kaʿb ibn al-Ashraf"], "Ibn ʿUmar reports in al-Bukhārī that when ʿAbdullāh ibn Ubayy died, the Prophet ﷺ prayed over him despite ʿUmar's objection, and then this verse was revealed."],
    de: ["Der gezeigte Vers, der das Totengebet für Heuchler verbietet, wurde offenbart, nachdem der Prophet ﷺ über wen gebetet hatte?", ["ʿAbdullāh ibn Ubayy ibn Salūl", "Abū Ṭālib", "Al-Walīd ibn al-Mughīra", "Kaʿb ibn al-Ashraf"], "Ibn ʿUmar berichtet bei al-Bukhārī, dass der Prophet ﷺ nach dem Tod von ʿAbdullāh ibn Ubayy trotz ʿUmars Einwand über ihn betete und dann dieser Vers offenbart wurde."],
    ar: ["نزلت الآية المعروضة في النهي عن الصلاة على المنافقين بعد أن صلّى النبي ﷺ على مَن؟", ["عبد الله بن أبي ابن سلول", "أبي طالب", "الوليد بن المغيرة", "كعب بن الأشرف"], "روى البخاري عن ابن عمر أن عبد الله بن أبي لما مات صلى عليه النبي ﷺ مع اعتراض عمر، ثم نزلت هذه الآية."] },
  { id: "ulr-059", s: "ulum", g: 3, d: 4, t: ["asbab-al-nuzul"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Tafsīr, Sūrat al-Ḥujurāt", v: "49:2",
    en: ["According to Ibn al-Zubayr in al-Bukhārī, the verse shown on lowering voices before the Prophet ﷺ followed a dispute between whom?", ["Abū Bakr and ʿUmar, over whom to appoint over the Banū Tamīm delegation", "Two men of the Anṣār, over the spoils of Ḥunayn", "The Aws and the Khazraj, over the hypocrites", "ʿAlī and al-ʿAbbās, over the keys of the Kaʿba"], "When a delegation of Banū Tamīm came, Abū Bakr proposed one man as their leader and ʿUmar another, and their voices rose in the Prophet's ﷺ presence. Ibn al-Zubayr said ʿUmar afterwards spoke so softly the Prophet ﷺ had to ask him to repeat."],
    de: ["Nach Ibn al-Zubayr bei al-Bukhārī folgte der gezeigte Vers über das Senken der Stimme vor dem Propheten ﷺ einem Streit zwischen wem?", ["Abū Bakr und ʿUmar, über den Anführer der Delegation der Banū Tamīm", "Zwei Männern der Anṣār, über die Beute von Ḥunayn", "Den Aws und den Khazraj, über die Heuchler", "ʿAlī und al-ʿAbbās, über die Schlüssel der Kaʿba"], "Als eine Delegation der Banū Tamīm kam, schlug Abū Bakr einen Mann als Anführer vor und ʿUmar einen anderen, und ihre Stimmen erhoben sich in Gegenwart des Propheten ﷺ. Ibn al-Zubayr sagte, ʿUmar habe danach so leise gesprochen, dass der Prophet ﷺ nachfragen musste."],
    ar: ["بحسب ابن الزبير عند البخاري، نزلت الآية المعروضة في خفض الصوت عند النبي ﷺ عقب خلاف بين مَن؟", ["أبي بكر وعمر في تأمير رجل على وفد بني تميم", "رجلين من الأنصار في غنائم حنين", "الأوس والخزرج في شأن المنافقين", "علي والعباس في مفاتيح الكعبة"], "لما قدم وفد بني تميم أشار أبو بكر بتأمير رجل وأشار عمر بآخر حتى ارتفعت أصواتهما عند النبي ﷺ فنزلت الآية، وذكر ابن الزبير أن عمر صار بعدها يخفض صوته حتى يستفهمه النبي ﷺ."] },
  { id: "ulr-060", s: "ulum", g: 3, d: 4, t: ["meccan-medinan", "definitions"], src: "al-Suyūṭī, al-Itqān, ch. on Meccan and Medinan", v: "5:3",
    en: ["The verse shown was revealed at ʿArafa in the Farewell Pilgrimage. How is it classified under the best-known (time-based) definition?", ["Medinan, because it came after the hijra", "Meccan, because it came down in the Meccan area", "Neither, since it was revealed on a journey", "Meccan, because it addresses the pilgrims"], "Under the time-based definition, everything revealed after the hijra is Medinan, even if it came down in Mecca, at ʿArafa or on a journey. A place-based definition would need a third category for such verses."],
    de: ["Der gezeigte Vers wurde in ʿArafa bei der Abschiedswallfahrt offenbart. Wie wird er nach der bekanntesten (zeitbezogenen) Definition eingeordnet?", ["Medinensisch, weil er nach der Hidschra kam", "Mekkanisch, weil er im mekkanischen Gebiet herabkam", "Weder noch, da er auf einer Reise offenbart wurde", "Mekkanisch, weil er die Pilger anspricht"], "Nach der zeitbezogenen Definition ist alles nach der Hidschra Offenbarte medinensisch, auch wenn es in Mekka, in ʿArafa oder auf einer Reise herabkam. Eine ortsbezogene Definition bräuchte für solche Verse eine dritte Kategorie."],
    ar: ["نزلت الآية المعروضة بعرفة في حجة الوداع. ما حكمها على التعريف الأشهر المعتمد على الزمان؟", ["مدنية لأنها نزلت بعد الهجرة", "مكية لأنها نزلت في نواحي مكة", "لا مكية ولا مدنية لنزولها في سفر", "مكية لأنها خاطبت الحجاج"], "على اعتبار الزمان كل ما نزل بعد الهجرة مدني وإن نزل بمكة أو عرفة أو في سفر، أما اعتبار المكان فيحتاج إلى قسم ثالث لمثل هذه الآيات."] },
  { id: "ulr-061", s: "ulum", g: 3, d: 4, t: ["meccan-medinan", "definitions"], src: "al-Suyūṭī, al-Itqān, ch. on Meccan and Medinan", v: "2:21",
    en: ["Some defined Meccan as what addresses 'O mankind' and Medinan as what addresses 'O you who believe'. Why does the verse shown weaken this definition?", ["It addresses mankind yet lies in a Medinan surah", "It addresses the believers yet lies in a Meccan surah", "It was revealed in Mecca after the hijra", "It contains no form of address at all"], "Al-Baqara is Medinan by agreement, yet the verse shown opens with an address to mankind; the same is true of al-Nisāʾ. So the addressee criterion is neither comprehensive nor exclusive, though it describes a general tendency."],
    de: ["Manche definierten als mekkanisch, was „O ihr Menschen“ anspricht, und als medinensisch, was „O ihr, die ihr glaubt“ anspricht. Warum schwächt der gezeigte Vers diese Definition?", ["Er spricht die Menschen an, steht aber in einer medinensischen Sure", "Er spricht die Gläubigen an, steht aber in einer mekkanischen Sure", "Er wurde nach der Hidschra in Mekka offenbart", "Er enthält überhaupt keine Anrede"], "Al-Baqara ist nach Übereinstimmung medinensisch, doch der gezeigte Vers beginnt mit einer Anrede an die Menschen; dasselbe gilt für al-Nisāʾ. Das Kriterium der Anrede ist daher weder umfassend noch ausschließend, beschreibt aber eine allgemeine Tendenz."],
    ar: ["عرّف بعضهم المكي بما خوطب فيه الناس عامة، والمدني بما خوطب فيه المؤمنون. لماذا تُضعف الآية المعروضة هذا التعريف؟", ["لأنها خطاب للناس وهي في سورة مدنية", "لأنها خطاب للمؤمنين وهي في سورة مكية", "لأنها نزلت بمكة بعد الهجرة", "لأنها خالية من أي خطاب"], "البقرة مدنية باتفاق ومع ذلك افتُتحت الآية المعروضة بخطاب الناس، ومثلها النساء، فضابط المخاطَب غير جامع ولا مانع وإن دلّ على الغالب."] },
  { id: "ulr-062", s: "ulum", g: 3, d: 3, t: ["meccan-medinan"], src: "al-Suyūṭī, al-Itqān, ch. on Meccan and Medinan (signs of the Meccan)",
    en: ["Al-Suyūṭī cites a rule of thumb about the word kallā. What is it?", ["Every surah in which kallā occurs is Meccan", "Every surah in which kallā occurs is Medinan", "Kallā occurs only in surahs with a prostration", "Kallā occurs only in the first half of the Quran"], "Kallā (a word of rebuke and denial) occurs only in Meccan surahs, all in the second half of the muṣḥaf. Its sternness suits the address to the obstinate Meccan opponents."],
    de: ["Al-Suyūṭī nennt eine Faustregel über das Wort kallā. Wie lautet sie?", ["Jede Sure, in der kallā vorkommt, ist mekkanisch", "Jede Sure, in der kallā vorkommt, ist medinensisch", "Kallā kommt nur in Suren mit einer Niederwerfung vor", "Kallā kommt nur in der ersten Hälfte des Korans vor"], "Kallā (ein Wort des Tadels und der Zurückweisung) kommt nur in mekkanischen Suren vor, alle in der zweiten Hälfte des muṣḥaf. Seine Strenge passt zur Ansprache der hartnäckigen mekkanischen Gegner."],
    ar: ["ذكر السيوطي ضابطًا في كلمة «كلا». ما هو؟", ["كل سورة فيها كلا فهي مكية", "كل سورة فيها كلا فهي مدنية", "لا ترد كلا إلا في سورة فيها سجدة", "لا ترد كلا إلا في النصف الأول من القرآن"], "كلا حرف ردع وزجر، ولم يرد إلا في سور مكية كلها في النصف الأخير من المصحف، وشدته تناسب خطاب المعاندين بمكة."] },
  { id: "ulr-063", s: "ulum", g: 3, d: 4, t: ["quran-names"], src: "Ibn Kathīr, Tafsīr, on 42:52", v: "42:52", w: 4,
    en: ["The highlighted word describes the revelation given to the Prophet ﷺ. Why is the Quran called by this word?", ["Because it gives life to hearts as the soul gives life to bodies", "Because it was brought by the angel called the Spirit", "Because it was revealed at night", "Because it cannot be seen, only heard"], "The Quran is called rūḥ because hearts live by it just as bodies live by the soul; without guidance the heart is as if dead. Jibrīl is called al-rūḥ al-amīn elsewhere, but here the word describes the revelation itself."],
    de: ["Das markierte Wort beschreibt die dem Propheten ﷺ gegebene Offenbarung. Warum wird der Koran mit diesem Wort bezeichnet?", ["Weil er die Herzen belebt, wie die Seele die Körper belebt", "Weil er vom Engel gebracht wurde, der „der Geist“ heißt", "Weil er nachts offenbart wurde", "Weil er nicht gesehen, nur gehört werden kann"], "Der Koran heißt rūḥ, weil die Herzen durch ihn leben, so wie die Körper durch die Seele leben; ohne Rechtleitung ist das Herz wie tot. Jibrīl heißt an anderer Stelle al-rūḥ al-amīn, hier aber beschreibt das Wort die Offenbarung selbst."],
    ar: ["الكلمة المظللة وصفٌ للوحي الذي أُعطيه النبي ﷺ. لماذا سُمّي القرآن بها؟", ["لأن به حياة القلوب كما أن بالروح حياة الأبدان", "لأن الذي نزل به ملك يسمى الروح", "لأنه نزل ليلًا", "لأنه لا يُرى وإنما يُسمع"], "سُمّي القرآن روحًا لأن القلوب تحيا به كما تحيا الأبدان بالأرواح، والقلب بلا هداية كالميت، وسُمّي جبريل الروح الأمين في موضع آخر، أما هنا فالوصف للوحي نفسه."] },
  { id: "ulr-064", s: "ulum", g: 3, d: 4, t: ["quran-names", "definitions"], src: "al-Zarqānī, Manāhil al-ʿIrfān, ch. on the definition of the Quran",
    en: ["In the technical definition of the Quran, which element excludes the ḥadīth qudsī?", ["That its recitation is an act of worship (al-mutaʿabbad bi-tilāwatih)", "That it is the speech of Allah", "That it was revealed to Muḥammad ﷺ", "That it is written in the muṣḥafs"], "The ḥadīth qudsī is also attributed to Allah and came to the Prophet ﷺ, so those elements do not exclude it. What sets the Quran apart is that reciting it is itself worship, valid in the prayer, and that it was revealed with its wording as a challenge."],
    de: ["Welches Element der fachlichen Definition des Korans schließt den ḥadīth qudsī aus?", ["Dass seine Rezitation ein Gottesdienst ist (al-mutaʿabbad bi-tilāwatih)", "Dass er die Rede Allahs ist", "Dass er Muḥammad ﷺ offenbart wurde", "Dass er in den Koranexemplaren geschrieben steht"], "Auch der ḥadīth qudsī wird Allah zugeschrieben und kam zum Propheten ﷺ; diese Elemente schließen ihn also nicht aus. Den Koran hebt ab, dass seine Rezitation selbst Gottesdienst ist, im Gebet gültig, und dass er mit seinem Wortlaut als Herausforderung offenbart wurde."],
    ar: ["في التعريف الاصطلاحي للقرآن، أي قيد يُخرج الحديث القدسي؟", ["المتعبَّد بتلاوته", "كلام الله", "المنزل على محمد ﷺ", "المكتوب في المصاحف"], "الحديث القدسي منسوب إلى الله وجاء به النبي ﷺ فلا تخرجه هذه القيود، وإنما يخرجه قيد التعبد بالتلاوة، إذ لا تصح به الصلاة، فضلًا عن أن القرآن نزل بلفظه متحدًّى به."] },
  { id: "ulr-065", s: "ulum", g: 3, d: 3, t: ["surah-count", "muqattaat"], src: "al-Suyūṭī, al-Itqān, ch. on the openings of the surahs",
    en: ["How many surahs open with the disconnected letters (al-ḥurūf al-muqaṭṭaʿa)?", ["29", "14", "19", "33"], "Twenty-nine surahs open with disconnected letters. The number 14 refers to the distinct letters used in these openings, which is a common source of confusion."],
    de: ["Wie viele Suren beginnen mit den getrennten Buchstaben (al-ḥurūf al-muqaṭṭaʿa)?", ["29", "14", "19", "33"], "Neunundzwanzig Suren beginnen mit getrennten Buchstaben. Die Zahl 14 bezeichnet die verschiedenen in diesen Anfängen verwendeten Buchstaben, was oft verwechselt wird."],
    ar: ["كم سورة افتُتحت بالحروف المقطعة؟", ["تسع وعشرون", "أربع عشرة", "تسع عشرة", "ثلاث وثلاثون"], "افتُتحت تسع وعشرون سورة بالحروف المقطعة، أما الأربعة عشر فعدد الحروف المستعملة في هذه الفواتح دون تكرار، وكثيرًا ما يُخلط بينهما."] },
  { id: "ulr-066", s: "ulum", g: 3, d: 3, t: ["scribes"], src: "Muslim, al-Ṣaḥīḥ, Kitāb Faḍāʾil al-Ṣaḥāba; Ibn Ḥajar, Fatḥ al-Bārī, Kitāb Faḍāʾil al-Qurʾān",
    en: ["Which of these Companions is counted among the scribes of the Prophet ﷺ?", ["Muʿāwiya ibn Abī Sufyān", "Abū Hurayra", "Anas ibn Mālik", "ʿAbdullāh ibn ʿAbbās"], "Muslim reports that Abū Sufyān asked the Prophet ﷺ to make Muʿāwiya his scribe and he agreed; Muʿāwiya is listed among the scribes by Ibn Ḥajar and others. The other three are great narrators but were not his scribes."],
    de: ["Welcher dieser Gefährten wird zu den Schreibern des Propheten ﷺ gezählt?", ["Muʿāwiya ibn Abī Sufyān", "Abū Hurayra", "Anas ibn Mālik", "ʿAbdullāh ibn ʿAbbās"], "Muslim berichtet, dass Abū Sufyān den Propheten ﷺ bat, Muʿāwiya zu seinem Schreiber zu machen, und er stimmte zu; Ibn Ḥajar und andere führen Muʿāwiya unter den Schreibern auf. Die anderen drei sind große Überlieferer, waren aber nicht seine Schreiber."],
    ar: ["أي هؤلاء الصحابة يُعدّ من كتّاب النبي ﷺ؟", ["معاوية بن أبي سفيان", "أبو هريرة", "أنس بن مالك", "عبد الله بن عباس"], "روى مسلم أن أبا سفيان سأل النبي ﷺ أن يتخذ معاوية كاتبًا فأجابه، وعدّه ابن حجر وغيره في كتّابه، أما الثلاثة الآخرون فمن كبار الرواة لا من الكتّاب."] },

  // ---------- stage 4 ----------
  { id: "ulr-067", s: "ulum", g: 4, d: 5, t: ["asbab-al-nuzul"], src: "al-Suyūṭī, al-Itqān, ch. on asbāb al-nuzūl (multiple occasions for one verse)",
    en: ["Two authentic, explicit reports name different occasions for one passage, and the events were close in time. How does al-Suyūṭī resolve this?", ["The passage was revealed after both events, so both are its occasion", "The later report is preferred and the earlier dropped", "Both reports are suspended for contradicting each other", "The report of the older Companion is preferred"], "Al-Suyūṭī ranks the cases: a sound report beats a weak one, and a stronger or eye-witness report is preferred. If both are equal and the events close in time, the passage came after both, as with the liʿān verses and the cases of Hilāl ibn Umayya and ʿUwaymir. If far apart, the passage may have been revealed more than once."],
    de: ["Zwei authentische, ausdrückliche Berichte nennen verschiedene Anlässe für eine Stelle, und die Ereignisse lagen zeitlich nah beieinander. Wie löst al-Suyūṭī das?", ["Die Stelle wurde nach beiden Ereignissen offenbart, beide sind ihr Anlass", "Der spätere Bericht wird bevorzugt, der frühere fallen gelassen", "Beide Berichte werden wegen des Widerspruchs ausgesetzt", "Der Bericht des älteren Gefährten wird bevorzugt"], "Al-Suyūṭī stuft die Fälle ab: Ein gesunder Bericht geht einem schwachen vor, ein stärkerer oder ein Augenzeugenbericht wird bevorzugt. Sind beide gleichwertig und die Ereignisse zeitnah, kam die Stelle nach beiden, wie bei den liʿān-Versen und den Fällen von Hilāl ibn Umayya und ʿUwaymir. Liegen sie weit auseinander, kann die Stelle mehrmals offenbart worden sein."],
    ar: ["روايتان صحيحتان صريحتان تذكران سببين مختلفين لآيات واحدة، والحادثتان متقاربتان زمنًا. كيف يوجّه السيوطي ذلك؟", ["تكون الآيات نزلت عقب الحادثتين فكلتاهما سبب", "تُقدَّم الرواية المتأخرة وتُترك الأخرى", "تُترك الروايتان للتعارض", "تُقدَّم رواية الصحابي الأقدم إسلامًا"], "رتّب السيوطي الأحوال: يُقدَّم الصحيح على الضعيف، والأقوى أو رواية الشاهد على غيرها، فإن تساويا وتقارب الزمن حُمل على النزول بعد السببين كآيات اللعان في قصتي هلال بن أمية وعويمر، وإن تباعد الزمن حُمل على تكرر النزول."] },
  { id: "ulr-068", s: "ulum", g: 4, d: 5, t: ["asbab-al-nuzul"], src: "al-Zarkashī, al-Burhān, first category (knowing the occasions of revelation); Ibn Taymiyya, Muqaddima fī Uṣūl al-Tafsīr",
    en: ["Why do al-Zarkashī and Ibn Taymiyya warn against treating every statement 'this verse was revealed concerning X' as an explicit occasion?", ["Such wording was often used to state what the verse covers, not what caused it", "Such wording only ever appears in weak chains", "Such wording refers to the place of revelation", "Such wording is used only for abrogated verses"], "Al-Zarkashī notes it was the habit of Companions and Successors to say 'it was revealed concerning this' meaning that the verse includes this ruling. Explicit causal wording, such as naming an event followed by 'so Allah revealed', is what establishes an occasion."],
    de: ["Warum warnen al-Zarkashī und Ibn Taymiyya davor, jede Aussage „dieser Vers wurde über X offenbart“ als ausdrücklichen Anlass zu behandeln?", ["Diese Formulierung diente oft dazu, anzugeben, was der Vers umfasst, nicht was ihn auslöste", "Diese Formulierung erscheint nur in schwachen Überlieferungsketten", "Diese Formulierung bezeichnet den Ort der Offenbarung", "Diese Formulierung wird nur für aufgehobene Verse verwendet"], "Al-Zarkashī stellt fest, dass Gefährten und Nachfolger gewohnt waren zu sagen, ein Vers sei „über dies“ offenbart worden, und damit meinten, dass er diese Regel einschließt. Eine ausdrücklich ursächliche Formulierung, etwa ein Ereignis gefolgt von „da offenbarte Allah“, begründet einen Anlass."],
    ar: ["لماذا نبّه الزركشي وابن تيمية على أنه لا يُجعل كل قول «نزلت هذه الآية في كذا» سببًا صريحًا؟", ["لأنه كثيرًا ما يُراد به بيان ما تتناوله الآية لا سببها", "لأنه لا يرد إلا بأسانيد ضعيفة", "لأنه يدل على مكان النزول", "لأنه لا يُستعمل إلا في الآيات المنسوخة"], "ذكر الزركشي أن من عادة الصحابة والتابعين أن يقول أحدهم «نزلت هذه الآية في كذا» ويريد أنها تتضمن هذا الحكم، أما الصيغة الصريحة كذكر الحادثة ثم «فأنزل الله» فهي التي يثبت بها السبب."] },
  { id: "ulr-069", s: "ulum", g: 4, d: 5, t: ["asbab-al-nuzul", "general-wording"], src: "al-Suyūṭī, al-Itqān, ch. on asbāb al-nuzūl (general wording and specific cause)", tr: ["comparative"],
    en: ["A minority held that the lesson lies in the specific cause, not the general wording. How did they still extend such rulings to others?", ["Through analogy (qiyās) or another proof showing the ruling is not restricted", "They did not; the ruling remained limited to the occasion forever", "Through the consensus that all occasions are examples", "Through the general wording, which they also accepted"], "Al-Suyūṭī notes that those who held the specificity view still applied the rulings to similar cases, but by qiyās or separate evidence rather than by the wording itself. So the practical difference between the two views is smaller than it appears."],
    de: ["Eine Minderheit vertrat, die Lehre liege im besonderen Anlass, nicht im allgemeinen Wortlaut. Wie dehnten sie solche Regeln dennoch auf andere aus?", ["Durch Analogieschluss (qiyās) oder einen anderen Beleg, dass die Regel nicht beschränkt ist", "Gar nicht; die Regel blieb für immer auf den Anlass beschränkt", "Durch den Konsens, dass alle Anlässe Beispiele sind", "Durch den allgemeinen Wortlaut, den sie ebenfalls anerkannten"], "Al-Suyūṭī bemerkt, dass auch die Vertreter der Besonderheitsansicht die Regeln auf ähnliche Fälle anwandten, jedoch durch qiyās oder gesonderte Belege statt durch den Wortlaut selbst. Der praktische Unterschied zwischen beiden Ansichten ist daher kleiner, als er scheint."],
    ar: ["ذهب قلة إلى أن العبرة بخصوص السبب لا بعموم اللفظ. فكيف عدّوا الحكم إلى غير من نزلت فيه؟", ["بالقياس أو بدليل آخر يدل على عدم الاختصاص", "لم يعدّوه، بل بقي الحكم مقصورًا على السبب", "بالإجماع على أن كل الأسباب أمثلة", "بعموم اللفظ الذي قبلوه أيضًا"], "ذكر السيوطي أن القائلين بخصوص السبب يعدّون الحكم إلى نظائر الواقعة، لكن بالقياس أو بدليل منفصل لا باللفظ نفسه، فالخلاف بين القولين في الثمرة العملية أضيق مما يبدو."] },
  { id: "ulr-070", s: "ulum", g: 4, d: 5, t: ["meccan-medinan"], src: "al-Suyūṭī, al-Itqān, ch. on Meccan and Medinan (signs of the Medinan)",
    en: ["Al-Suyūṭī cites the rule that every surah mentioning the hypocrites is Medinan, with one exception. Which surah is it?", ["Al-ʿAnkabūt", "Al-Aḥzāb", "Al-Rūm", "Luqmān"], "Hypocrisy appeared in Medina, so surahs mentioning the hypocrites are Medinan, except al-ʿAnkabūt, which is Meccan and yet speaks of them (in 29:11). Al-Aḥzāb mentions them too but is Medinan, so it is no exception."],
    de: ["Al-Suyūṭī nennt die Regel, dass jede Sure, die die Heuchler erwähnt, medinensisch ist, mit einer Ausnahme. Welche Sure ist es?", ["Al-ʿAnkabūt", "Al-Aḥzāb", "Al-Rūm", "Luqmān"], "Die Heuchelei trat in Medina auf, daher sind Suren, die die Heuchler erwähnen, medinensisch, außer al-ʿAnkabūt, die mekkanisch ist und dennoch von ihnen spricht (in 29:11). Al-Aḥzāb erwähnt sie auch, ist aber medinensisch und daher keine Ausnahme."],
    ar: ["ذكر السيوطي ضابطًا: كل سورة فيها ذكر المنافقين فهي مدنية إلا سورة واحدة. ما هي؟", ["العنكبوت", "الأحزاب", "الروم", "لقمان"], "ظهر النفاق بالمدينة، فالسور التي فيها ذكر المنافقين مدنية إلا العنكبوت فهي مكية وفيها ذكرهم (29:11)، أما الأحزاب ففيها ذكرهم وهي مدنية فليست استثناءً."] },
  { id: "ulr-071", s: "ulum", g: 4, d: 4, t: ["meccan-medinan", "muqattaat"], src: "al-Suyūṭī, al-Itqān, ch. on Meccan and Medinan (signs of the Meccan)",
    en: ["Every surah opening with disconnected letters is Meccan, with two agreed exceptions. Which are they?", ["Al-Baqara and Āl ʿImrān", "Yūnus and Hūd", "Maryam and Ṭā-Hā", "Luqmān and al-Sajda"], "Al-Suyūṭī gives the rule with the exception of al-Baqara and Āl ʿImrān, which are Medinan; he adds that there is disagreement about al-Raʿd. Yūnus, Hūd, Maryam, Ṭā-Hā, Luqmān and al-Sajda are Meccan."],
    de: ["Jede Sure, die mit getrennten Buchstaben beginnt, ist mekkanisch, mit zwei unstrittigen Ausnahmen. Welche sind es?", ["Al-Baqara und Āl ʿImrān", "Yūnus und Hūd", "Maryam und Ṭā-Hā", "Luqmān und al-Sajda"], "Al-Suyūṭī nennt die Regel mit der Ausnahme von al-Baqara und Āl ʿImrān, die medinensisch sind; er fügt hinzu, dass über al-Raʿd Uneinigkeit besteht. Yūnus, Hūd, Maryam, Ṭā-Hā, Luqmān und al-Sajda sind mekkanisch."],
    ar: ["كل سورة افتُتحت بالحروف المقطعة مكية إلا سورتين باتفاق. ما هما؟", ["البقرة وآل عمران", "يونس وهود", "مريم وطه", "لقمان والسجدة"], "ذكر السيوطي هذا الضابط واستثنى البقرة وآل عمران لأنهما مدنيتان، ونبّه على الخلاف في الرعد، أما يونس وهود ومريم وطه ولقمان والسجدة فمكيات."] },
  { id: "ulr-072", s: "ulum", g: 4, d: 5, t: ["meccan-medinan", "first-revelation"], src: "al-Suyūṭī, al-Itqān, ch. on Meccan and Medinan; al-Bukhārī, Kitāb al-Tafsīr, Sūrat al-Fātiḥa", v: "15:87", tr: ["jumhur"],
    en: ["The majority hold al-Fātiḥa to be Meccan, against a view attributed to Mujāhid. Which argument draws on the verse shown?", ["It is in a Meccan surah and mentions the 'seven oft-repeated', which the Prophet ﷺ identified as al-Fātiḥa", "It mentions prayer, which was only prescribed in Mecca", "It addresses the people of Mecca by name", "It states that al-Fātiḥa was revealed in Ḥirāʾ"], "Al-Ḥijr is Meccan, and in it Allah reminds the Prophet ﷺ that He has already given him the seven oft-repeated; the hadith of Abū Saʿīd ibn al-Muʿallā in al-Bukhārī identifies them with al-Fātiḥa. So al-Fātiḥa existed before the hijra. Some also said it was revealed twice."],
    de: ["Die Mehrheit hält al-Fātiḥa für mekkanisch, gegen eine Mujāhid zugeschriebene Ansicht. Welches Argument stützt sich auf den gezeigten Vers?", ["Er steht in einer mekkanischen Sure und erwähnt die „sieben oft wiederholten“, die der Prophet ﷺ als al-Fātiḥa bestimmte", "Er erwähnt das Gebet, das nur in Mekka vorgeschrieben wurde", "Er spricht die Leute von Mekka namentlich an", "Er sagt, al-Fātiḥa sei in Ḥirāʾ offenbart worden"], "Al-Ḥijr ist mekkanisch, und darin erinnert Allah den Propheten ﷺ daran, dass Er ihm die sieben oft wiederholten bereits gegeben hat; der Hadith von Abū Saʿīd ibn al-Muʿallā bei al-Bukhārī setzt sie mit al-Fātiḥa gleich. Also gab es al-Fātiḥa schon vor der Hidschra. Manche sagten auch, sie sei zweimal offenbart worden."],
    ar: ["الجمهور على أن الفاتحة مكية خلافًا لقول نُسب إلى مجاهد. أي استدلال يعتمد على الآية المعروضة؟", ["أنها في سورة مكية وذكرت السبع المثاني التي فسّرها النبي ﷺ بالفاتحة", "أنها ذكرت الصلاة ولم تُفرض إلا بمكة", "أنها خاطبت أهل مكة بأسمائهم", "أنها نصّت على نزول الفاتحة في حراء"], "سورة الحجر مكية، وفيها امتنان على النبي ﷺ بإيتائه السبع المثاني، وفسّرها حديث أبي سعيد بن المعلى عند البخاري بالفاتحة، فدلّ على نزولها قبل الهجرة، وقال بعضهم إنها نزلت مرتين."] },
  { id: "ulr-073", s: "ulum", g: 4, d: 5, t: ["meccan-medinan"], src: "al-Suyūṭī, al-Itqān, ch. on Meccan and Medinan (Medinan verses in Meccan surahs)", v: "73:20", tr: ["comparative"],
    en: ["Some scholars consider the verse shown Medinan although al-Muzzammil is Meccan. Which feature of the verse do they point to?", ["It mentions people fighting in the path of Allah", "It addresses the People of the Book", "It names the hypocrites of Medina", "It refers to the change of qibla"], "The verse speaks of some who travel seeking Allah's bounty and others who fight in His path, and commands giving zakāt; fighting was prescribed after the hijra. Others keep it Meccan, reading the mention of fighting as a foretelling."],
    de: ["Manche Gelehrte halten den gezeigten Vers für medinensisch, obwohl al-Muzzammil mekkanisch ist. Auf welches Merkmal des Verses verweisen sie?", ["Er erwähnt Menschen, die auf dem Weg Allahs kämpfen", "Er spricht die Leute der Schrift an", "Er nennt die Heuchler Medinas", "Er bezieht sich auf den Wechsel der qibla"], "Der Vers spricht von einigen, die reisen, um Allahs Huld zu suchen, und anderen, die auf Seinem Weg kämpfen, und gebietet die zakāt; der Kampf wurde nach der Hidschra vorgeschrieben. Andere halten ihn für mekkanisch und verstehen die Erwähnung des Kampfes als Vorhersage."],
    ar: ["يرى بعض العلماء أن الآية المعروضة مدنية مع أن سورة المزمل مكية. ما السمة التي يستدلون بها؟", ["ذكر المقاتلين في سبيل الله", "خطاب أهل الكتاب", "تسمية منافقي المدينة", "الإشارة إلى تحويل القبلة"], "ذكرت الآية قومًا يضربون في الأرض يبتغون من فضل الله وآخرين يقاتلون في سبيله وأمرت بإيتاء الزكاة، والقتال إنما شُرع بعد الهجرة، وأبقاها آخرون مكية وحملوا ذكر القتال على الإخبار بما سيكون."] },
  { id: "ulr-074", s: "ulum", g: 4, d: 5, t: ["quran-names", "definitions"], src: "al-Suyūṭī, al-Itqān, ch. on the names of the Quran",
    en: ["Which scholar held that 'al-Qurān' (read without hamza) is a proper name of Allah's Book, not derived from qaraʾa, like al-Tawrāh and al-Injīl?", ["Al-Shāfiʿī", "Al-Liḥyānī", "Al-Zajjāj", "Abū ʿUbayda"], "Al-Suyūṭī reports that al-Shāfiʿī, who read with the Meccan reading of Ibn Kathīr, held it to be a non-derived name. Al-Liḥyānī and others made it a verbal noun of qaraʾa (to recite), while al-Zajjāj and Abū ʿUbayda linked it to qarʾ in the sense of gathering."],
    de: ["Welcher Gelehrte vertrat, dass „al-Qurān“ (ohne hamza gelesen) ein Eigenname des Buches Allahs ist, nicht von qaraʾa abgeleitet, wie al-Tawrāh und al-Injīl?", ["Al-Shāfiʿī", "Al-Liḥyānī", "Al-Zajjāj", "Abū ʿUbayda"], "Al-Suyūṭī berichtet, dass al-Shāfiʿī, der nach der mekkanischen Lesart Ibn Kathīrs las, ihn für einen nicht abgeleiteten Namen hielt. Al-Liḥyānī und andere sahen darin ein Verbalnomen von qaraʾa (rezitieren), während al-Zajjāj und Abū ʿUbayda es mit qarʾ im Sinne von Sammeln verbanden."],
    ar: ["مَن العالم الذي ذهب إلى أن «القُرَان» بلا همز اسمٌ علم لكتاب الله غير مشتق من قرأ، كالتوراة والإنجيل؟", ["الشافعي", "اللحياني", "الزجاج", "أبو عبيدة"], "نقل السيوطي عن الشافعي، وكان يقرأ بقراءة ابن كثير المكي، أنه اسم غير مشتق، وجعله اللحياني وغيره مصدرًا لقرأ بمعنى تلا، وربطه الزجاج وأبو عبيدة بالقَرْء بمعنى الجمع."] },
  { id: "ulr-075", s: "ulum", g: 4, d: 5, t: ["verse-count"], src: "al-Dānī, al-Bayān fī ʿAdd Āy al-Qurʾān, on Sūrat al-Fātiḥa", v: "1:7", tr: ["comparative"],
    en: ["All counting schools give al-Fātiḥa seven verses. How do the schools that do not count the basmala as a verse (e.g. the Madinan and Basran) reach seven?", ["They place a verse-end within the verse shown, after the mention of those Allah has favoured", "They count the āmīn after al-Fātiḥa as a verse", "They divide the first verse of praise into two", "They count the basmala of the next surah"], "The Kufan and Meccan counts make the basmala verse one and the verse shown a single verse. The Madinan, Basran and Shāmī counts drop the basmala and instead end a verse after the mention of those whom Allah has favoured, splitting the verse shown into two."],
    de: ["Alle Zählschulen geben al-Fātiḥa sieben Verse. Wie kommen die Schulen, die die basmala nicht als Vers zählen (z. B. die medinensische und basrische), auf sieben?", ["Sie setzen ein Versende innerhalb des gezeigten Verses, nach der Erwähnung derer, denen Allah Gunst erwiesen hat", "Sie zählen das āmīn nach al-Fātiḥa als Vers", "Sie teilen den ersten Lobpreisvers in zwei", "Sie zählen die basmala der nächsten Sure"], "Die kufische und die mekkanische Zählung machen die basmala zu Vers eins und den gezeigten Vers zu einem einzigen Vers. Die medinensische, basrische und syrische Zählung lassen die basmala weg und setzen stattdessen ein Versende nach der Erwähnung derer, denen Allah Gunst erwiesen hat, sodass der gezeigte Vers in zwei geteilt wird."],
    ar: ["اتفقت مذاهب العدّ على أن الفاتحة سبع آيات. فكيف تبلغ المذاهب التي لا تعدّ البسملة آية (كالمدني والبصري) سبعًا؟", ["تعدّ رأس آية في أثناء الآية المعروضة بعد ذكر المنعَم عليهم", "تعدّ التأمين بعد الفاتحة آية", "تقسم آية الحمد الأولى قسمين", "تعدّ بسملة السورة التالية"], "يعدّ الكوفي والمكي البسملة الآية الأولى ويجعلان الآية المعروضة آية واحدة، أما المدني والبصري والشامي فلا يعدّون البسملة، ويعدّون رأس آية بعد ذكر المنعَم عليهم، فتنقسم الآية المعروضة آيتين."] },
  { id: "ulr-076", s: "ulum", g: 4, d: 5, t: ["scribes"], src: "Ibn Ḥajar, Fatḥ al-Bārī, Kitāb Faḍāʾil al-Qurʾān, chapter on the scribe of the Prophet ﷺ; Ibn ʿAbd al-Barr, al-Istīʿāb, entry Ubayy ibn Kaʿb",
    en: ["Which Companion is reported to have been the first to write for the Prophet ﷺ after his arrival in Medina?", ["Ubayy ibn Kaʿb", "Zayd ibn Thābit", "Muʿāwiya ibn Abī Sufyān", "ʿAbdullāh ibn Masʿūd"], "Ibn ʿAbd al-Barr and Ibn Ḥajar report that Ubayy ibn Kaʿb was the first to write for him in Medina; when Ubayy was absent Zayd ibn Thābit wrote, and Zayd later became the most constant scribe. Muʿāwiya wrote only after the conquest of Mecca."],
    de: ["Welcher Gefährte soll als Erster nach der Ankunft des Propheten ﷺ in Medina für ihn geschrieben haben?", ["Ubayy ibn Kaʿb", "Zayd ibn Thābit", "Muʿāwiya ibn Abī Sufyān", "ʿAbdullāh ibn Masʿūd"], "Ibn ʿAbd al-Barr und Ibn Ḥajar berichten, dass Ubayy ibn Kaʿb als Erster in Medina für ihn schrieb; war Ubayy abwesend, schrieb Zayd ibn Thābit, der später der beständigste Schreiber wurde. Muʿāwiya schrieb erst nach der Eroberung Mekkas."],
    ar: ["مَن الصحابي الذي يُذكر أنه أول من كتب للنبي ﷺ بعد مقدمه المدينة؟", ["أبي بن كعب", "زيد بن ثابت", "معاوية بن أبي سفيان", "عبد الله بن مسعود"], "ذكر ابن عبد البر وابن حجر أن أبي بن كعب أول من كتب له بالمدينة، فإذا غاب كتب زيد بن ثابت، ثم صار زيد ألزمهم للكتابة، أما معاوية فكتب بعد فتح مكة."] },
];
